  function setSubject(subject) {
    if (!subjects[subject] || subject===currentSubject) return;
    saveCurrentSubject();
    currentSubject=subject;
    currentClassId=classesBySubject[subject]?.some(item=>item.id===activeClassesBySubject[subject])?activeClassesBySubject[subject]:(classesBySubject[subject]?.[0]?.id||null);
    restoreSubjectState(subject);
    if(!subjects[subject].custom){if(customPagesFor(subject).length)buildCustomSubjectPanels(subject);applyBuiltInPageVisibility(subject)}
    applyActiveBuiltInPageLabels();
    const isLatin=subjects[subject].group==='latin',isCustom=!!subjects[subject].custom,hasExtraPages=customPagesFor(subject).length>0;
    $('addPageQuick').classList.remove('hide');$('addExamQuick').classList.remove('hide');
    $('normalTabs').classList.toggle('hide',isLatin||isCustom);$('customTabs').classList.toggle('hide',!isCustom&&!hasExtraPages);$('customPanels').classList.toggle('hide',!isCustom&&!hasExtraPages);
    $('latinTabs').classList.toggle('hide',!isLatin);
    $('normalPanels').classList.toggle('hide',isLatin||isCustom);
    $('latinPanels').classList.toggle('hide',!isLatin||isCustom);
    for (const id of Object.keys(subjects)) $('subject-'+id).setAttribute('aria-selected',String(id===subject));
    $('eyebrow').textContent=`Noten-Manager · ${subjects[subject].label}`;
    $('intro').textContent='Noten berechnen · Klausuren, Tests und Mitarbeit verwalten · Halbjahre auswerten.';
    renderAll(true);
    setPage(activePage);
    updateEmptyAppState();
    refreshExamNavigation();
  }
