  const makeTaskId=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2,9)}`}`;
  const roundSchoolGrade=value=>Math.max(1,Math.min(6,Math.ceil(Number(value)-0.5-1e-10)));
  const taskGradeClass=(value,system='gradePoints')=>{const grade=system==='participation'?Math.round(Number(value)*100)/100:Number(value);if(!Number.isFinite(grade))return '';if(system==='grades'||system==='participation'){const tendency=system==='grades'&&grade>1&&grade<6&&Math.abs(grade*3-Math.round(grade*3))<1e-6&&!Number.isInteger(Math.round(grade*3)/3),between=(system==='participation'&&grade>1&&grade<6&&!Number.isInteger(grade))||tendency?` participation-between-${Math.floor(grade)}-${Math.ceil(grade)}${grade%1<5/12?' participation-lean-low':grade%1>7/12?' participation-lean-high':''}`:'';return grade<=0?'':`g${Math.max(1,Math.min(6,roundSchoolGrade(grade)))}${between}`;}/* Notenpunkte mit Tendenz (z. B. 9 = 3+) erhalten dieselbe Schraffur wie die Schulnote; 4 Punkte behalten ihre eigene, immer sichtbare Schraffur. */
    /* 8.25: Durchschnitte in Notenpunkten nach der gerundeten Punktzahl einfärben (3,5 → 4 Punkte = immer schraffiert) */const pg=Number.isInteger(grade)?grade:Math.max(0,Math.min(15,Math.floor(grade+0.5+1e-9)));const pointTendency=Number.isInteger(pg)&&pg>=1&&pg<=13&&pg!==4&&pg%3!==2,equivalent=(17-pg)/3;return `g${Math.min(6,Math.floor((15-pg)/3)+1)}${pg===4?' grade-four-fail':''}${pointTendency?` participation-between-${Math.floor(equivalent)}-${Math.ceil(equivalent)} ${equivalent%1<.5?'participation-lean-low':'participation-lean-high'}`:''}`};
  const taskGradeSystem=(subject,pageKey)=>subjectExamGroups(subject).some(group=>['performance','tests'].includes(group.type)&&group.pages.includes(pageKey))?'participation':subjectExamGroups(subject).some(group=>group.type==='semester'&&group.pages.includes(pageKey))?'semester':classUsesGradePoints(subject)?'gradePoints':classUsesSchoolGrades(subject)?'grades':taskBasisPages(subject,pageKey).map(page=>page.system).find(system=>system==='grades'||system==='gradePoints')||customPagesFor(subject).find(page=>page.key===pageKey)?.gradeSystem||'gradePoints';
