    if(classUsesGradePoints(subject)&&!data.upperPointsDefaultInitialized&&subjectExamGroups(subject).some(g=>['performance','tests'].includes(g.type)&&g.pages.includes(pageKey))){data.numericParticipation=true;data.upperPointsDefaultInitialized=true}
