    if(typeof data.resultTendencies!=='boolean')data.resultTendencies=!!data.tendencies&&!data.resultRounded;
    if(!Array.isArray(data.students))data.students=[{id:makeTaskId('student'),name:'',grades:{},placeholder:true}];
    if(data.weightMode==='ratio')applyTaskRatios(data);
    data.students.forEach(student=>{student.grades??={};student.rawScores??={}});
    if(subject===currentSubject&&currentClassId==='class-demo-extra-erdkunde'&&!pageKey.startsWith('tasks-demo-')&&!data.demoSchoolGrades){for(const student of data.students)for(const [id,value] of Object.entries(student.grades))if(value!==''&&value!==null&&value!=='x'&&Number.isFinite(Number(value)))student.grades[id]=roundSchoolGrade((17-Number(value))/3);data.demoSchoolGrades=true;data.tendencies=false}
