      if(page&&page.system!=='tasks')return {key,label:page.label,base:page.base,system:page.system};
      const builtin={points:{label:builtInPageName(subject,'points'),base:'points',system:'grades'},'new-format':{label:builtInPageName(subject,'new-format'),base:'points',system:'gradePoints'},words:{label:builtInPageName(subject,'words'),base:'text',system:'grades'},'latin-points':{label:builtInPageName(subject,'latin-points'),base:'points',system:'grades'},'latin-format':{label:builtInPageName(subject,'latin-format'),base:'points',system:'gradePoints'}}[key];
