  // Leere Namenszeilen ohne Eintragungen (z. B. die Startzeile einer neuen Seite) entfallen beim Import von Namen.
  function studentHasEntries(student){return ['grades','rawScores','statuses'].some(key=>Object.values(student?.[key]||{}).some(value=>value!==''&&value!==null&&value!==undefined))}
  function isEmptyStudent(student){return !String(student?.name||'').trim()&&!studentHasEntries(student)}
