  function openPasteNamesDialog(pageKey){ pendingPastePageKey=pageKey;$('pasteNamesFile').value='';$('pasteNamesInput').value='';$('pasteNamesError').textContent='';$('pasteNamesDialog').showModal();$('pasteNamesInput').focus() }
        function classroomParseDelimitedText(text) {
            text = text.replace(/^\uFEFF/, '');
            const candidates = [',', ';', '\t'];
            function parseWith(delimiter) {
                const rows = [];
                let row = [], field = '', quoted = false;
                for (let i = 0; i < text.length; i++) {
                    const ch = text[i];
                    if (quoted) {
                        if (ch === '"' && text[i + 1] === '"') { field += '"'; i++; }
                        else if (ch === '"') quoted = false;
                        else field += ch;
                    } else if (ch === '"' && field.length === 0) quoted = true;
                    else if (ch === delimiter) { row.push(field); field = ''; }
                    else if (ch === '\n' || ch === '\r') {
                        if (ch === '\r' && text[i + 1] === '\n') i++;
                        row.push(field); rows.push(row); row = []; field = '';
                    } else field += ch;
                }
                row.push(field);
                if (row.some(cell => cell.length) || !rows.length) rows.push(row);
                return rows;
            }
            const counts = candidates.map(delimiter => {
                const rows = parseWith(delimiter);
                return { delimiter, score: rows.slice(0, 10).reduce((n, row) => n + Math.max(0, row.length - 1), 0) };
            }).sort((a, b) => b.score - a.score);
            return parseWith(counts[0].delimiter).filter(row => row.some(cell => cell.trim()));
        }


  function classroomImportNames(text){
    const norm=value=>String(value||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z]/g,'');
    const rows=classroomParseDelimitedText(text),head=rows[0]||[];
    const surname=head.findIndex(v=>['nachname','familienname','lastname','surname'].includes(norm(v))),given=head.findIndex(v=>['vorname','firstname','givenname'].includes(norm(v))),full=head.findIndex(v=>['name','schuler','schulerin','schulername','fullname'].includes(norm(v)));
    if(surname>=0&&given>=0)return rows.slice(1).map(r=>[r[surname]?.trim(),r[given]?.trim()].filter(Boolean).join(', ')).filter(Boolean);
    if(full>=0)return rows.slice(1).map(r=>r[full]?.trim()).filter(Boolean);
    const gender=v=>/^(m|w|d|male|female|mannlich|weiblich)$/i.test(norm(v));
    return rows.map(r=>r.length>1&&!gender(r[1])?[r[0]?.trim(),r[1]?.trim()].filter(Boolean).join(', '):r[0]?.trim()).filter(Boolean);
  }
  $('pasteNamesFile').addEventListener('change',async event=>{
    const file=event.target.files[0];if(!file)return;
    try{
      const buffer=await file.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(buffer);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1252').decode(buffer);
      let names;
      if(/\.json$/i.test(file.name)){
        const data=JSON.parse(text),list=Array.isArray(data)?data:data.schuelerEinzel||data.students||data.einzel;
        if(!Array.isArray(list))throw new Error('Die JSON-Datei enthält keine Schülerliste.');
        names=list.map(item=>typeof item==='string'?item:[item.nachname||item.lastName,item.vorname||item.firstName].filter(Boolean).join(', ')||item.name||'').map(name=>String(name).trim()).filter(Boolean);
      }else names=classroomImportNames(text);
      if(!names.length)throw new Error('Die Datei enthält keine Namen.');
      $('pasteNamesInput').value=names.join('\n');$('pasteNamesError').textContent=names.length+' Namen erkannt. Bitte prüfen und „Namen hinzufügen“ wählen.';
    }catch(error){$('pasteNamesError').textContent='Import nicht möglich: '+error.message}finally{event.target.value=''}
  });
