        seen.add(pageKey);const row=document.createElement('label');row.className='export-option';
        const input=document.createElement('input');input.type='checkbox';input.dataset.exportPage=page.key;input.checked=page.key===activePage;
        const span=document.createElement('span');span.textContent=label;row.append(input,span);customOptions.append(row)
