        if(group.type==='homework')return groupPages.some(page=>homeworkPageData(currentSubject,page.key).assignments.length>0);
        if(group.type==='tests')return groupPages.some(page=>{const data=taskPageData(currentSubject,page.key);return data.tasks.some((task,index)=>task.date||String(task.name||'').trim()!==`Test ${index+1}`)||data.students.some(student=>data.tasks.some(task=>[student.grades?.[task.id],student.rawScores?.[task.id]].some(value=>value!==undefined&&value!==null&&value!=='')))});
