      const schoolYearGroups=groups.filter(group=>group.type==='schoolYear'&&group.pages?.length&&isExportableGroup(group));
      if(schoolYearGroups.length){addHeading('Schuljahr');for(const group of schoolYearGroups)addGroup(group)}
      const unassignedGroups=groups.filter(group=>!['halfYear','schoolYear'].includes(group.type)&&!group.halfYearId&&group.pages?.length&&isExportableGroup(group));
      if(unassignedGroups.length){addHeading('Weitere Bereiche');for(const group of unassignedGroups)addGroup(group)}
