document.addEventListener('paste',event=>{const panel=event.target.closest('[data-custom-panel]'),group=classroomCentralGroup(classroomSourceKey());if(!panel||!group)return;setTimeout(()=>{const data=customPageValues(currentSubject,panel.dataset.customPanel);for(const person of data.students||[])for(const task of data.tasks||[])if(task.date&&person.grades?.[task.id]==='x')parent.postMessage({type:'classroom:attendance',classId:group.id,studentId:person.id,date:task.date,absent:true},'*');parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*')},0)});

document.addEventListener('click',event=>{if(event.target.closest('[data-task-action="clear-grades"]'))setTimeout(()=>parent.postMessage({type:'classroom:rosters',snapshot:classroomRosterSnapshot()},'*'),0)});

document.addEventListener('click',event=>{if(!event.target.closest('[data-gender-roster]'))return;if(!currentClassId){alert('Bitte zuerst eine Klasse auswählen.');return}parent.postMessage({type:'classroom:gender-roster',source:classroomSourceKey(),snapshot:classroomRosterSnapshot()},'*')});

// Commit shared names as one edit instead of letting canonical refresh undo typing.
