 function applyNs(){for(const b of document.querySelectorAll('button.notenspiegel-button,[data-task-action="notenspiegel"],[data-homework-action="notenspiegel"]')){if(b.querySelector(':scope>svg'))continue;if(b.textContent.trim()!=='Notenspiegel')continue;b.innerHTML=NS+'<span class="pi-lbl">Notenspiegel</span>';b.classList.add('pi-icon');b.setAttribute('aria-label','Notenspiegel');if(!b.title)b.title='Notenspiegel'}}
 /* 10.48: Schülerübersicht (zwei Personen) und „Eingaben löschen“ (roter Papierkorb) als Symbol */
 const SO='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8.5" r="3.2"/><path d="M3.5 19.5c.6-3.3 2.8-5 5.5-5s4.9 1.7 5.5 5"/><circle cx="16.5" cy="9.5" r="2.6"/><path d="M15.8 14.6c2.4.1 4.1 1.6 4.7 4.4"/></svg>';
 const TR='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 12.5A1.5 1.5 0 0 0 8.5 21h7a1.5 1.5 0 0 0 1.5-1.5L18 7M9 7V4.5A1.5 1.5 0 0 1 10.5 3h3A1.5 1.5 0 0 1 15 4.5V7"/></svg>';
 function iconize(sel,text,svg,title,cls){for(const b of document.querySelectorAll(sel)){if(b.querySelector(':scope>svg'))continue;if(b.textContent.trim()!==text)continue;b.innerHTML=(typeof svg==='function'?svg():svg)+'<span class="pi-lbl">'+text+'</span>';b.classList.add('pi-icon');if(cls)b.classList.add(cls);b.setAttribute('aria-label',text);b.title=title}}
 /* 10.50: Fortschritt (Mini-Fortschrittsbalken, Verlauf über die ganze Länge) und Übersicht (Tabelle) */
