  const metadata=sheet.rows.filter(row=>row.number<header.number).flatMap(row=>[...row.cells.values()]),classLabel=metadata.find(v=>/^klasse\s/i.test(v)),subject=metadata.find(v=>/^fach\s/i.test(v))?.replace(/^fach\s+/i,'');return {names,records,dates,classLabel,subject,corrections};
