/* ==== noten/fit-panel.js ==== */
/* 10.15: Weiße Hauptfläche passt genau in den sichtbaren Bereich (Mac/iPad).
   Die Seite selbst scrollt nicht mehr – gescrollt wird nur noch innerhalb der Fläche bzw. der Tabelle. */
(function(){
 const root=document.documentElement,GAP=16;
 let box=null;
 const usable=()=>!root.classList.contains('ph-lite')&&innerWidth>=700&&innerHeight>=420;
 const panels=()=>[...document.querySelectorAll('main>section.panel,main>div>section.panel')].filter(e=>e.getClientRects().length&&!e.closest('dialog'));
 function clear(){if(box){box.style.height='';box.classList.remove('fit-box');box=null}if(root.classList.contains('fit-panel'))root.classList.remove('fit-panel')}
 function fit(){
  if(!usable()){clear();return}
  const list=panels();if(list.length!==1){clear();return}
  const p=list[0];
  if(box&&box!==p){const y=box.scrollTop;box.style.height='';box.classList.remove('fit-box');p.scrollTop=y}
  box=p;if(!root.classList.contains('fit-panel'))root.classList.add('fit-panel');if(!p.classList.contains('fit-box'))p.classList.add('fit-box');
  if(document.scrollingElement.scrollTop)document.scrollingElement.scrollTop=0;
  const top=p.getBoundingClientRect().top,h=Math.max(260,Math.round(innerHeight-top-gap()));
  if(Math.abs((parseFloat(p.style.height)||0)-h)>1){p.style.height=h+'px';try{window.classroomSizeWraps?.()}catch{}}
 }
 /* 10.17: Abstand unten = Abstand links/rechts. Unter dem Rahmen liegt evtl. schon der Home-Balken-Abstand der App (iPad) */
 function gap(){const m=document.querySelector('main');const side=m?parseFloat(getComputedStyle(m).paddingLeft)||GAP:GAP;
  if(root.classList.contains('fs-view'))return side;let below=0;try{const fr=frameElement,pd=parent.document;if(fr&&pd){below=Math.max(0,pd.documentElement.clientHeight-fr.getBoundingClientRect().bottom)}}catch{}
  /* 10.31: einheitlich 12 px über dem Bildschirmrand (wie Unterrichts-Manager) */
  return Math.max(4,Math.round(12-below))}
 window.classroomFitBox=()=>box&&root.classList.contains('fit-panel')?box:null;
 let planned=false;const run=()=>{if(planned)return;planned=true;requestAnimationFrame(()=>{planned=false;try{fit()}catch(e){console.warn(e)}})};
 addEventListener('resize',run);
 window.visualViewport?.addEventListener('resize',run);
 if(typeof classroomOnDomChange==='function')classroomOnDomChange(run);else new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});
 /* class/hidden-Wechsel lösen keinen childList-Change aus */
 new MutationObserver(run).observe(document.querySelector('main')||document.body,{attributes:true,attributeFilter:['class','hidden'],subtree:true});
 /* Seitenwechsel: Fläche wieder oben beginnen */
 let lastKey='';const pageKey=()=>{try{return [currentSubject,currentClassId,currentHalfYearId,typeof activePage==='object'?activePage?.id:activePage].join('|')}catch{return ''}};
 try{classroomHooks.add('setPage','fit-panel',{after(){const k=pageKey();if(k!==lastKey){lastKey=k;if(box)box.scrollTop=0}run()}})}catch(e){console.warn(e)}
 addEventListener('load',run);run();setTimeout(run,600);
 const st=document.createElement('style');st.textContent=`
html.fit-panel,html.fit-panel body{height:100%;overflow:hidden;overscroll-behavior:none}
html.fit-panel body[data-module=noten] main{padding-bottom:0!important}
/* 10.16: Gummiband in Fläche und Tabelle (außen bleibt fest) */
html.fit-panel .panel.fit-box{overflow:auto;overscroll-behavior:auto;-webkit-overflow-scrolling:touch;margin-bottom:0!important}
html.fit-panel body[data-module=noten] .panel.fit-box .table-wrap:not(#_){overscroll-behavior:auto}
@media print{html.fit-panel,html.fit-panel body{height:auto;overflow:visible}html.fit-panel .panel.fit-box{height:auto!important;overflow:visible}}`;
 document.head.append(st);
})();
;

/* ==== noten/fullscreen-view.js ==== */
/* 10.16/10.17: Knopf „Vollbild“ (nur Symbol) rechts neben dem Schraffur-Schalter (Mac/iPad).
   Vollbild gilt für den ganzen Noten-Bereich (Titel, Schalter, Tabelle) – so übersteht es jedes Neuzeichnen. */
(function(){
 const root=document.documentElement;
 const IN='<path d="M4 9V5a1 1 0 0 1 1-1h4M15 4h4a1 1 0 0 1 1 1v4M20 15v4a1 1 0 0 1-1 1h-4M9 20H5a1 1 0 0 1-1-1v-4"/>';
 const OUT='<path d="M9 4v4a1 1 0 0 1-1 1H4M20 9h-4a1 1 0 0 1-1-1V4M15 20v-4a1 1 0 0 1 1-1h4M4 15h4a1 1 0 0 1 1 1v4"/>';
 const fsEl=()=>document.fullscreenElement||document.webkitFullscreenElement||null;
 const canReal=()=>!!(document.fullscreenEnabled||document.webkitFullscreenEnabled)&&!!(root.requestFullscreen||root.webkitRequestFullscreen);
 const can=()=>canReal()||canPseudo();
  /* 10.17: Wo der Browser kein echtes Vollbild für den Bereich erlaubt (z. B. iPad-App), legt sich der Noten-Bereich über die ganze App */
 let pseudo=false;
 const pdoc=()=>{try{return frameElement&&parent.document}catch{return null}};
 const canPseudo=()=>!!pdoc();
 function setPseudo(on){const d=pdoc();if(!d)return;pseudo=on;
  if(!d.getElementById('noten-fs-style')){const st=d.createElement('style');st.id='noten-fs-style';st.textContent='body.noten-fs .workspace{position:fixed!important;inset:0!important;z-index:9800!important;background:#f6f8fc;padding:env(safe-area-inset-top) env(safe-area-inset-right) 0 env(safe-area-inset-left);box-sizing:border-box}body.noten-fs .workspace>iframe:not(#view-noten){visibility:hidden}';d.head.append(st)}
  d.body.classList.toggle('noten-fs',on);changed()}
 const isOn=()=>!!fsEl()||pseudo;
 function toggle(){
  try{
   if(pseudo){setPseudo(false);return}
   if(fsEl()){(document.exitFullscreen||document.webkitExitFullscreen).call(document);return}
   if(!canReal()){setPseudo(true);return}
   const r=(root.requestFullscreen||root.webkitRequestFullscreen).call(root);r?.catch?.(()=>setPseudo(true));
   /* Safari ohne Promise: wenn nach kurzer Zeit kein Vollbild da ist, Ersatz nehmen */
   if(!r||!r.then)setTimeout(()=>{if(!fsEl()&&!pseudo)setPseudo(true)},400);
  }catch(e){setPseudo(true)}
 }
 const vis=e=>!!e&&e.getClientRects().length>0;
 function paint(b){const on=isOn(),k=on?'on':'off';if(b.dataset.fs===k)return;b.dataset.fs=k;
  b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(on?OUT:IN)+'</svg>';
  b.title=on?'Vollbild beenden (Esc)':'Vollbild: Tabelle samt Kopfleiste';b.setAttribute('aria-label',on?'Vollbild beenden':'Vollbild');b.setAttribute('aria-pressed',on?'true':'false')}
 function place(){
  const show=can()&&!root.classList.contains('ph-lite');
  for(const b of document.querySelectorAll('.fs-btn'))if(!show||!vis(b.parentElement))b.remove();
  if(!show)return;
  /* 10.19: überall gleiche Reihenfolge am Ende der Leiste: … · Auffällig · Drucken · Vollbild */
  const print=[...document.querySelectorAll('[data-page-print]')].find(vis);
  const hatch=[...document.querySelectorAll('.hatch-seg')].find(vis);
  const anchor=print||hatch;if(!anchor)return;
  /* 10.49: Vollbild bleibt oben bei den Ansicht-Schaltern, auch wenn Drucken unten bei den Aktionen steht */const box=(anchor.parentElement?.matches('.task-actions,.semester-table-tools,.custom-heading-controls')&&anchor.parentElement.parentElement?.querySelector(':scope>.oral-display-actions'))||anchor.parentElement;let b=box.querySelector(':scope>.fs-btn');
  if(!b){b=document.createElement('button');b.type='button';b.className='fs-btn';b.addEventListener('click',e=>{e.stopPropagation();toggle()});box.append(b)}
  paint(b);
  const setOrd=(e,o)=>{if(e&&e.style.getPropertyValue('order')!==o)e.style.setProperty('order',o,'important')};
  if(print){const pb=print.parentElement,ew=pb.querySelector(':scope>.ew-btn');setOrd(print,'28');setOrd(ew,'29');setOrd(pb.querySelector(':scope>.clear-students-button'),'30');setOrd(b,'30')}
  else setOrd(b,'98');
  hideIntro();
 }
 /* 10.18: Im Vollbild Erklärtext und Gewichtungsfelder zwischen Knopfleiste und Tabelle ausblenden */
 function hideIntro(){
  const on=isOn();const old=[...document.querySelectorAll('.fs-hide')];
  if(!on){old.forEach(e=>e.classList.remove('fs-hide'));return}
  const p=window.classroomFitBox?.()||[...document.querySelectorAll('main section.panel')].find(vis);if(!p)return;
  const title=p.querySelector(':scope>.section-title');const w=[...p.querySelectorAll('.table-wrap')].find(vis);if(!title||!w)return;
  let holder=w;while(holder.parentElement&&holder.parentElement!==p)holder=holder.parentElement;if(holder.parentElement!==p)return;
  const want=new Set();for(let e=title.nextElementSibling;e&&e!==holder;e=e.nextElementSibling){if(!e.querySelector('table,button,select'))want.add(e)}
  for(const e of old)if(!want.has(e))e.classList.remove('fs-hide');
  for(const e of want)if(!e.classList.contains('fs-hide'))e.classList.add('fs-hide')}
 let planned=false;const run=()=>{if(planned)return;planned=true;requestAnimationFrame(()=>{planned=false;try{place()}catch(e){console.warn(e)}})};
 if(typeof classroomOnDomChange==='function')classroomOnDomChange(run);else new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});
 function changed(){root.classList.toggle('fs-view',isOn());run();setTimeout(()=>{dispatchEvent(new Event('resize'))},60)}
 addEventListener('keydown',e=>{if(e.key==='Escape'&&pseudo&&!document.querySelector('dialog[open]')){e.preventDefault();setPseudo(false)}});
 document.addEventListener('fullscreenchange',changed);document.addEventListener('webkitfullscreenchange',changed);
 addEventListener('resize',run);run();setTimeout(run,800);
 window.classroomFullscreen={toggle,isOn};
 const st=document.createElement('style');st.textContent=`
.fs-btn{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;padding:0;border:1px solid #d5deea;border-radius:10px;background:#fff;color:#2f5f9b;font:inherit;font-size:.86rem;font-weight:600;line-height:1;cursor:pointer;white-space:nowrap;flex:none}
.fs-btn:hover{background:#f3f7fc}/* 10.87: Vollbild aktiv = blau ausgefüllt */html body .fs-btn[aria-pressed=true]:not(#_):not(#__):not(#___){background:#2f5f9b!important;border-color:#2f5f9b!important;color:#fff!important}.fs-btn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
html.ph-lite .fs-btn{display:none!important}
html.fs-view,html.fs-view body{background:#f6f8fc}
html.fs-view body[data-module=noten] main{padding:12px 12px 0!important;max-width:none!important}
html.fs-view .fs-hide{display:none!important}
@media print{.fs-btn{display:none!important}}`;
 document.head.append(st);
})();
;

/* ==== noten/rubber-band.js ==== */
/* 10.17/10.18: Gummiband am Mac (Trackpad/Maus). Safari/Chrome am Mac federn nur die ganze Seite nach,
   nicht Bereiche, die in sich scrollen. Hier nachgebildet wie bei iOS: Am Ende zieht der Inhalt gebremst mit
   und federt sofort weich zurück – auch während der Trackpad-Schwung noch läuft. iPad/iPhone machen das selbst.
   Tabellen (Kompaktansicht) werden über einen Rand verschoben, weil Safari verschobene Tabellen mit festem Kopf nicht sauber zeichnet. */
(function(){
 const fine=matchMedia('(hover:hover) and (pointer:fine)');
 const root=document.documentElement,MAX=90;
 let el=null,off=0,raf=0,lastInput=0;
 const canScrollY=e=>e.scrollHeight-e.clientHeight>1&&/(auto|scroll)/.test(getComputedStyle(e).overflowY);
 function chain(start){const out=[];for(let e=start;e&&e!==document.body&&e!==root;e=e.parentElement){if(e.nodeType===1&&canScrollY(e))out.push(e)}return out}
 function paint(target,y){
  const kids=[...target.children];
  if(kids.length===1&&kids[0].tagName==='TABLE'){const t=kids[0];
   if(y>0){t.style.marginTop=y.toFixed(1)+'px';t.style.marginBottom=''}
   else if(y<0){t.style.marginTop='';t.style.marginBottom=(-y).toFixed(1)+'px';target.scrollTop=target.scrollHeight}
   else{t.style.marginTop='';t.style.marginBottom=''}
  }else for(const c of kids)c.style.transform=y?'translateY('+y.toFixed(1)+'px)':''}
 function tick(){
  raf=0;if(!el)return;
  /* Rückfederung: läuft immer, solange gezogen ist – nach dem letzten Impuls schneller */
  const quiet=performance.now()-lastInput>60;
  off*=quiet?0.80:0.93;
  if(Math.abs(off)<0.4){off=0;paint(el,0);el=null;return}
  paint(el,off);raf=requestAnimationFrame(tick)}
 addEventListener('wheel',e=>{
  if(!fine.matches||root.classList.contains('ph-lite')||e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||!e.deltaY)return;
  const list=chain(e.target);if(!list.length)return;
  const down=e.deltaY>0;
  if(list.some(x=>down?x.scrollTop<x.scrollHeight-x.clientHeight-1:x.scrollTop>0))return;
  const target=list[0];
  if(el&&el!==target){paint(el,0);off=0}
  el=target;lastInput=performance.now();
  /* Bremse: je weiter gezogen, desto weniger bewegt sich der Inhalt */
  const k=1-Math.min(Math.abs(off)/MAX,1);
  off=Math.max(-MAX,Math.min(MAX,off-e.deltaY*0.22*k*k));
  if(!raf)raf=requestAnimationFrame(tick);
 },{passive:true});
})();
;

