   const items=(j.r||[]).filter(x=>Array.isArray(x)&&typeof x[0]==='string'&&/^cm-/.test(x[0]));const main=items[0];let exists=false;try{exists=!!(main&&localStorage.getItem(main[0]))}catch{}
