/* ==== noten/grammar-gen.js ==== */
/* 10.72: Grammatik-Tests (Latein) – Aufgaben aus den Formen-Regeln von vocab-pdf.js.
   Keine Buchinhalte: Wörter kommen aus deinem eigenen Vokabular (falls geladen) oder aus einer kleinen Grundliste.
   Aufgabenarten: tab (Tabelle, ggf. mit Vorgaben = Lückentabelle), det (Form bestimmen), inp (Form bilden).
   Gleiche Formen in m/f/n (bzw. in einer Zeile) zählen je ½ Punkt. */
(()=>{
 const V=()=>window.classroomVocabPdf;
 const norm=s=>V().plain(String(s||'')).replace(/j/g,'i').replace(/[^a-z\s]/g,' ').replace(/\s+/g,' ').trim();
 const rngOf=seed=>{let a=seed>>>0||1;return ()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}};
 const shuffle=(arr,r)=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 const pick=(arr,r)=>arr[Math.floor(r()*arr.length)];
 const NUMS=['Sg.','Pl.'],GEN=['m','f','n'];
 const NOUNS=[['amīcus','amīcī m.'],['puella','puellae f.'],['templum','templī n.'],['servus','servī m.'],['via','viae f.'],['dōnum','dōnī n.'],['senātor','senātōris m.'],['urbs','urbis f.'],['corpus','corporis n.'],['māter','mātris f.'],['rēx','rēgis m.'],['nōmen','nōminis n.']];
 const NOUNS_E=[['rēs','reī f.'],['diēs','diēī m.'],['spēs','speī f.'],['faciēs','faciēī f.']];
 const NOUNS_U=[['manus','manūs f.'],['exercitus','exercitūs m.'],['senātus','senātūs m.'],['cursus','cursūs m.']];
 const NOUNS_3=[['corpus','corporis n.'],['nōmen','nōminis n.'],['tempus','temporis n.'],['mare','maris n.'],['animal','animālis n.'],['urbs','urbis f.'],['rēx','rēgis m.']];
 const ADJ_AO=[['bonus','-a, -um'],['magnus','-a, -um'],['longus','-a, -um'],['pulcher','-chra, -chrum'],['līber','-era, -erum'],['miser','-era, -erum']];
 const ADJ_3=[['ācer','ācris, ācre'],['gravis','-e'],['fortis','-e'],['audāx','audācis'],['fēlīx','fēlīcis'],['omnis','-e']];
 const VERBS=[['laudāre','laudō, laudāvī, laudātum'],['vocāre','vocō, vocāvī, vocātum'],['monēre','moneō, monuī, monitum'],['vidēre','videō, vīdī, vīsum'],['audīre','audiō, audīvī, audītum'],['mittere','mittō, mīsī, missum'],['capere','capiō, cēpī, captum'],['dūcere','dūcō, dūxī, ductum'],['scrībere','scrībō, scrīpsī, scrīptum'],['relinquere','relinquō, relīquī, relictum'],['dēlēre','dēleō, dēlēvī, dēlētum'],['petere','petō, petīvī, petītum']];
 const TNAME={praes:'Präsens',impf:'Imperfekt',fut:'Futur I',perf:'Perfekt',plqpf:'Plusquamperfekt'};
 /* ---------- Wortquellen: eigenes Vokabular (bis zur Lektion) + Grundliste ---------- */
 let libMemo={k:'',v:null};
 function libLex(lesson){const raw=(()=>{try{return localStorage.getItem('classroom-vocab-library-v1')||''}catch{return ''}})(),key=lesson+'|'+raw.length;if(libMemo.k===key)return libMemo.v;const out=[];
  try{const lib=JSON.parse(raw||'null'),lim=V().lessonOrder(String(lesson));for(const [k,l] of Object.entries(lib?.lessons||{})){if(V().lessonOrder(k)>lim)continue;for(const sec of l.sections||[])for(const e of sec.entries||[]){try{const a=V().analyze(e);if(a&&a.kind&&a.kind!=='?'&&a.kind!=='x')out.push(a)}catch{}}}}catch{}
  libMemo={k:key,v:out};return out}
 const builtN=list=>list.map(([l,i])=>{const p=V().nounParadigm(l,i);return p?{...p,lemma:l}:null}).filter(Boolean);
 const builtA=list=>list.map(([l,i])=>{const p=V().adjParadigm(l,i);return p?{...p,lemma:l,info:i}:null}).filter(Boolean);
 const builtV=list=>list.map(([l,i])=>{const p=V().verbParadigm(l,i);return p?{...p,lemma:l,info:i}:null}).filter(Boolean);
 const uniq=list=>{const s=new Set();return list.filter(x=>{const k=norm(x.lemma);if(s.has(k))return false;s.add(k);return true})};
 function nounPool(lesson,decl){let lib=libLex(lesson).filter(x=>x.kind==='n'&&!x.pluralOnly&&!x.unsure&&x.forms&&(!decl||x.decl===decl));const b=builtN(decl==='e'?NOUNS_E:decl==='u'?NOUNS_U:decl==='3'?NOUNS_3:NOUNS);return uniq([...lib,...b])}
 function adjPool(lesson,kind){const lib=libLex(lesson).filter(x=>x.kind==='a'&&!x.pron&&!x.pluralOnly&&(kind==='ao'?x.adjAO:x.adj3));return uniq([...lib,...builtA(kind==='ao'?ADJ_AO:ADJ_3)])}
 function verbPool(lesson,need){const ok=v=>v&&v.kind==='v'&&!v.dep&&!v.irr&&v.conj&&v.conj!=='irr'&&need(v);return uniq([...libLex(lesson).filter(ok),...builtV(VERBS).filter(ok)])}
 /* ---------- Aufgaben-Bausteine ---------- */
 function tabItem(ti,rows,cols,get,opt={}){const r=opt.r||Math.random;const sol=rows.map(rk=>cols.map(c=>get(rk,c)??null));
  const hf=sol.map(row=>row.map((f,ci)=>!!f&&!opt.noHalf&&row.some((g,cj)=>cj!==ci&&g&&norm(g)===norm(f))));
  const gv=sol.map(row=>row.map(()=>false));
  if(opt.gap){sol.forEach((row,ri)=>{const idx=row.map((f,ci)=>f?ci:-1).filter(i=>i>=0);const give=shuffle(idx,r).slice(0,Math.max(0,Math.min(idx.length-1,Math.round(idx.length*(opt.gap||.35)+r()-.5))));give.forEach(ci=>gv[ri][ci]=true)})}
  return {k:'tab',ti,rw:rows.map(x=>opt.rowLabel?opt.rowLabel(x):x),cl:cols.map(x=>opt.colLabel?opt.colLabel(x):x),sol,gv,hf}}
 function detItem(f,dims,analyses){return {k:'det',f,d:dims,sol:analyses}}
 function inpItem(p,sub,sol){return {k:'inp',p,sub,sol}}
 const pts=it=>it.k==='tab'?it.sol.reduce((a,row,ri)=>a+row.reduce((b,f,ci)=>b+(f&&!it.gv[ri][ci]?(it.hf[ri][ci]?.5:1):0),0),0):it.k==='det'?it.d.length:it.sub.length;
 /* ---------- Nominalformen ---------- */
 const caseRows=(L,onlySg)=>[...(onlySg||!L.plural?['Sg.']:NUMS)].flatMap(n=>CASES().filter(c=>L.cases.has(c)).map(c=>c+' '+n));
 const CASES=()=>V().CASES;
 
 function nomDims(L,genus){const d=[['Kasus',CASES().filter(c=>L.cases.has(c))],['Numerus',L.plural?NUMS:['Sg.']]];if(genus)d.push(['Genus',GEN]);return d}
 const splitKey=k=>{const p=k.replace(/^(PPP|PPA)\s+/,'').split(' ');return [p[0],p[1],p[2]].filter(Boolean)};
 function detFromForms(forms,n,r,L,genus,prefix){/* forms: {key: form} */const groups={};for(const [k,f] of Object.entries(forms)){if(prefix&&!k.startsWith(prefix))continue;const [c,num]=splitKey(k);if(!L.cases.has(c)||(!L.plural&&num==='Pl.'))continue;(groups[norm(f)]??={f,keys:[]}).keys.push(k)}
  return shuffle(Object.values(groups),r).slice(0,n).map(g=>detItem(g.f,nomDims(L,genus),g.keys.map(splitKey)))}
 /* ---------- Generatoren ---------- */
 const PRON_LABEL={'quī':'quī, quae, quod',is:'is, ea, id',hic:'hic, haec, hoc',ille:'ille, illa, illud',ipse:'ipse, ipsa, ipsum',iste:'iste, ista, istud'};
 function gen(code,lesson){const L=V().learned(/^T/.test(lesson)?99:lesson),[kind,arg]=code.split(':');const all={...L,cases:new Set(V().CASES),plural:true};
  if(kind==='pron'){const p=V().pronParadigm(arg);if(!p)return null;const lab=PRON_LABEL[arg]||arg;
   const tbl=(r,gap)=>tabItem((gap?'Ergänze':'Fülle')+' die Tabelle: '+lab,caseRows(all),GEN,(rk,g)=>p.forms[rk+' '+g],{r,gap:gap?.35:0});
   const types=[['tab','Leere Tabelle',0,r=>[tbl(r,false)]],['gap','Lückentabelle',0,r=>[tbl(r,true)]],['det','Formen bestimmen',1,(r,n)=>detFromForms(p.forms,n,r,all,true).map(it=>({...it,ti:'Bestimme die Form von '+lab}))]];
   if(arg!=='quī')types.push(['kng','Passende Form zum Substantiv',1,(r,n)=>kngNoun(r,n,lesson,all,(c,num,g)=>p.forms[c+' '+num+' '+g],'Setze '+arg+' in die passende Form')]);
   return {label:lab,types}}
  if(kind==='adj'){const pool=adjPool(lesson,arg);if(!pool.length)return null;const lab=arg==='ao'?'Adjektiv der a-/o-Deklination':'Adjektiv der 3. Deklination';
   const tbl=(r,gap)=>{const a=pick(pool,r);return tabItem((gap?'Ergänze':'Fülle')+' die Tabelle: '+a.lemma+(a.info?', '+a.info:''),caseRows(all),GEN,(rk,g)=>a.forms[rk+' '+g],{r,gap:gap?.35:0})};
   return {label:lab,types:[['tab','Leere Tabelle',0,r=>[tbl(r,false)]],['gap','Lückentabelle',0,r=>[tbl(r,true)]],
    ['kng','Passende Form zum Substantiv',1,(r,n)=>{const out=[];for(let i=0;i<n;i++){const a=pick(pool,r);out.push(...kngNoun(r,1,lesson,all,(c,num,g)=>a.forms[c+' '+num+' '+g],'Setze '+a.lemma+' in die passende Form',a.lemma))}return out}],
    ['det','Formen bestimmen',1,(r,n)=>{const out=[];const ps=shuffle(pool,r);for(let i=0;out.length<n&&i<n*3;i++){const a=ps[i%ps.length];out.push(...detFromForms(a.forms,1,r,all,true).filter(x=>!out.some(y=>norm(y.f)===norm(x.f))).map(it=>({...it,ti:'Bestimme Kasus, Numerus, Genus ('+a.lemma+')'})))}return out}]]}}
  if(kind==='noun'){const pool=nounPool(lesson,arg||'');if(!pool.length)return null;const lab=arg==='e'?'Substantiv der e-Deklination':arg==='u'?'Substantiv der u-Deklination':arg==='3'?'Substantiv der 3. Deklination':'Substantive';
   const tbl=(r,gap)=>{const nn=pick(pool,r);return tabItem((gap?'Ergänze':'Dekliniere')+': '+nn.lemma+', '+(nn.gen||'')+' '+nn.genus.join('/')+'.',caseRows(L).filter(k=>nn.forms[k]).map(k=>k.split(' ')[0]).filter((c,i,a)=>a.indexOf(c)===i),L.plural?NUMS:['Sg.'],(c,num)=>nn.forms[c+' '+num],{r,gap:gap?.35:0,noHalf:true})};
   return {label:lab,types:[['tab','Leere Tabelle',0,r=>[tbl(r,false)]],['gap','Lückentabelle',0,r=>[tbl(r,true)]],
    ['det','Formen bestimmen',1,(r,n)=>{const out=[];const ps=shuffle(pool,r);for(let i=0;out.length<n&&i<n*4;i++){const nn=ps[i%ps.length];out.push(...detFromForms(nn.forms,1,r,L,false).filter(x=>!out.some(y=>norm(y.f)===norm(x.f))).map(it=>({...it,ti:'Bestimme Kasus und Numerus ('+nn.lemma+')'})))}return out}]]}}
  if(kind==='ppp'||kind==='ppa'){const P=kind==='ppp'?'pppForms':'ppaForms',pool=verbPool(lesson,v=>Object.keys(v[P]||{}).length>0&&(kind==='ppa'||!!v.ppp));if(!pool.length)return null;const pre=kind.toUpperCase();
   const types=[['kng',pre+' passend zum Substantiv bilden',1,(r,n)=>{const out=[];for(let i=0;i<n;i++){const v=pick(pool,r);out.push(...kngNoun(r,1,lesson,all,(c,num,g)=>v[P][pre+' '+c+' '+num+' '+g],'Bilde das '+pre+' von '+v.lemma+' passend zum Substantiv',v.lemma))}return out}],
    ['tab',pre+'-Tabelle',0,r=>{const v=pick(pool,r);const nom=v[P][pre+' Nom. Sg. m'];return [tabItem('Fülle die Tabelle: '+pre+' von '+v.lemma+' ('+nom+')',caseRows(all),GEN,(rk,g)=>v[P][pre+' '+rk+' '+g],{r})]}]];
   types.unshift(['det',pre+'-Formen bestimmen',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const v=pick(pool,r);out.push(...detFromForms(v[P],1,r,all,true).filter(x=>!out.some(y=>norm(y.f)===norm(x.f))).map(it=>({...it,ti:'Bestimme Kasus, Numerus, Genus des '+pre})))}return out}],
    ['herk','Woher kommt die Form? (Grundform nennen)',1,(r,n)=>herkunft(r,n,pool,v=>Object.values(v[P]),'Woher kommt das '+pre+'?')]);
   if(kind==='ppp')types.push(['stamm','Stammformen bis zum PPP',1,(r,n)=>shuffle(pool.filter(v=>v.also?.length>=2),r).slice(0,n).map(v=>({...inpItem(v.lemma+', '+v.sg,['Perfekt (1. Sg.)','PPP'],[[v.also[0]],[v.ppp,v.ppp.replace(/um$/,'us')]]),ti:'Nenne Perfekt und PPP'}))]);
   return {label:pre,types}}
  if(kind==='verb'||kind==='irr')return verbGen(kind,arg,lesson,L);
  if(kind==='adv')return advGen(arg,lesson);
  if(kind==='gerund'||kind==='gerundiv')return gerGen(kind,lesson,all);
  if(kind==='absabs')return absGen(lesson,all);
  return null}
 /* Form → Grundform (Infinitiv, 1. Sg. Präs.) – „Woher kommt auditum?“ */
 function herkunft(r,n,pool,formsOf,ti){const out=[];let guard=0;while(out.length<n&&guard++<n*20){const v=pick(pool,r),fs=formsOf(v).filter(Boolean);if(!fs.length)continue;const f=pick(fs,r);if(norm(f)===norm(v.lemma)||out.some(y=>norm(y.p)===norm(f)))continue;out.push({...inpItem(f,['Infinitiv','1. Sg. Präs.'],[[v.lemma],[v.sg]]),ti})}return out}
 /* Adverbien */
 function advOf(a){const L=a.lemma,lp=V().plain(L);if(a.adjAO){if(lp==='bonus')return 'bene';if(lp==='magnus'||lp==='parvus'||lp==='multus')return null;const gen=a.forms['Gen. Sg. m']||'';const st=gen.replace(/[īi]$/,'');return st?st+'ē':null}
  if(a.adj3){if(/^(omnis|cunctus|ceterus)$/.test(lp))return null;if(lp==='facilis')return 'facile';if(lp==='difficilis')return 'difficile';if(lp==='audax')return 'audācter';const gen=a.forms['Gen. Sg. m']||'',st=gen.replace(/is$/,'');if(!st)return null;if(/nt$/.test(V().plain(st)))return st+'er';return st+'iter'}return null}
 function advGen(arg,lesson){const pool=adjPool(lesson,arg==='3'?'3':'ao').filter(a=>advOf(a));if(!pool.length)return null;
  return {label:'Adverbien',types:[['erk','Adverb erkennen (Adjektiv nennen)',1,(r,n)=>shuffle(pool,r).slice(0,n).map(a=>({...inpItem(advOf(a),['Adjektiv (Nom. Sg. m)'],[[a.lemma]]),ti:'Zu welchem Adjektiv gehört das Adverb?'}))],
   ['bild','Adverb bilden',1,(r,n)=>shuffle(pool,r).slice(0,n).map(a=>({...inpItem(a.lemma,['Adverb'],[[advOf(a)]]),ti:'Bilde das Adverb'}))]]}}
 /* Gerundium und Gerundivum: Stamm aus dem PPA (laudant- → laudand-) */
 const gStem=v=>{const g=v.ppaForms?.['PPA Gen. Sg. m'];return g?g.replace(/is$/,'').replace(/nt$/,'nd'):null};
 const END_AO={m:[['us','ī','ō','um','ō'],['ī','ōrum','īs','ōs','īs']],f:[['a','ae','ae','am','ā'],['ae','ārum','īs','ās','īs']],n:[['um','ī','ō','um','ō'],['a','ōrum','īs','a','īs']]};
 const gerundivForms=st=>{const f={};for(const g of GEN)NUMS.forEach((num,ni)=>END_AO[g][ni].forEach((e,i)=>f[V().CASES[i]+' '+num+' '+g]=st+e));return f};
 function gerGen(kind,lesson,all){const pool=verbPool(lesson,v=>!!gStem(v));if(!pool.length)return null;
  if(kind==='gerund'){const GC=['Gen.','Dat.','Akk.','Abl.'],form=(v,c)=>gStem(v)+({'Gen.':'ī','Dat.':'ō','Akk.':'um','Abl.':'ō'})[c];
   return {label:'Gerundium',types:[['det','Kasus des Gerundiums bestimmen',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const v=pick(pool,r),ctx=['Gen.','Akk.','in','Abl.'][out.length%4],c=ctx==='in'?'Abl.':ctx,f=form(v,c),pf=(c==='Akk.'?'ad ':ctx==='in'?'in ':'')+f;if(out.some(y=>norm(y.f).endsWith(norm(f))))continue;out.push({...detItem(pf,[['Kasus',GC]],(ctx==='in'?['Abl.']:GC.filter(x=>form(v,x)===f)).map(x=>[x])),ti:'Bestimme den Kasus des Gerundiums'})}return shuffle(out,r)}],
    ['herk','Woher kommt die Form? (Grundform nennen)',1,(r,n)=>herkunft(r,n,pool,v=>GC.map(c=>form(v,c)),'Woher kommt das Gerundium?')],
    ['bild','Gerundium bilden',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const v=pick(pool,r),c=pick(GC,r);const p=v.lemma+' – '+c;if(out.some(y=>y.p===p))continue;out.push({...inpItem(p,['Gerundium'],[[form(v,c)]]),ti:'Bilde das Gerundium im angegebenen Kasus'})}return out}]]}}
  const fo=v=>gerundivForms(gStem(v));
  return {label:'Gerundivum',types:[['det','Gerundivum bestimmen (KNG)',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const v=pick(pool,r);out.push(...detFromForms(fo(v),1,r,all,true).filter(x=>!out.some(y=>norm(y.f)===norm(x.f))).map(it=>({...it,ti:'Bestimme Kasus, Numerus, Genus des Gerundivums'})))}return out}],
   ['herk','Woher kommt die Form? (Grundform nennen)',1,(r,n)=>herkunft(r,n,pool,v=>Object.values(fo(v)),'Woher kommt das Gerundivum?')],
   ['kng','Gerundivum passend zum Substantiv bilden',1,(r,n)=>{const out=[];for(let i=0;i<n;i++){const v=pick(pool,r),F=fo(v);out.push(...kngNoun(r,1,lesson,all,(c,num,g)=>F[c+' '+num+' '+g],'Bilde das Gerundivum von '+v.lemma+' passend zum Substantiv',v.lemma))}return out}]]}}
 /* Ablativus absolutus: Substantiv + Partizip im Ablativ */
 function absGen(lesson,all){const L=V().learned(/^T/.test(lesson)?99:lesson);const pool=verbPool(lesson,v=>Object.keys(v.pppForms||{}).length>0),nouns=nounPool(lesson,'').filter(nn=>nn.forms['Abl. Sg.']&&nn.forms['Abl. Pl.']);if(!pool.length||!nouns.length)return null;
  const make=r=>{const v=pick(pool,r),nn=pick(nouns,r),num=r()<.5?'Sg.':'Pl.',g=nn.genus[0],ppa=L.ppa&&r()<.4&&v.ppaForms?.['PPA Abl. '+num+' '+g];const part=ppa?v.ppaForms['PPA Abl. '+num+' '+g]:v.pppForms['PPP Abl. '+num+' '+g];if(!part)return null;return {v,nn,num,ppa:!!ppa,phrase:nn.forms['Abl. '+num]+' '+part}};
  return {label:'Ablativus absolutus',types:[['erk','Abl. abs. erkennen (Zeitverhältnis, Genus verbi)',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const m=make(r);if(!m||out.some(y=>y.f===m.phrase))continue;out.push({...detItem(m.phrase,[['Zeitverhältnis',['vorzeitig','gleichzeitig']],['Genus verbi',['aktiv','passiv']]],[[m.ppa?'gleichzeitig':'vorzeitig',m.ppa?'aktiv':'passiv']]),ti:'Bestimme den Ablativus absolutus'})}return out}],
   ['herk','Woher kommt das Partizip? (Grundform nennen)',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const m=make(r);if(!m||out.some(y=>y.p===m.phrase))continue;out.push({...inpItem(m.phrase,['Infinitiv','1. Sg. Präs.'],[[m.v.lemma],[m.v.sg]]),ti:'Woher kommt das Partizip?'})}return out}],
   ['bild','Abl. abs. bilden',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*20){const m=make(r);if(!m)continue;const p=m.nn.lemma+' ('+m.num+') + '+m.v.lemma+' ('+(m.ppa?'PPA':'PPP')+')';if(out.some(y=>y.p===p))continue;const [a,b]=m.phrase.split(' ');out.push({...inpItem(p,['Abl. abs.'],[[m.phrase,b+' '+a]]),ti:'Bilde den Ablativus absolutus'})}return out}]]}}
 /* Substantiv vorgegeben → Form eines Adjektivs/Pronomens/Partizips in gleicher KNG */
 function kngNoun(r,n,lesson,L,formOf,ti,shown){const pool=nounPool(lesson,'');const out=[];let guard=0;
  while(out.length<n&&guard++<n*20){const nn=pick(pool,r),keys=Object.keys(nn.forms).filter(k=>{const [c,num]=k.split(' ');return L.cases.has(c)&&(L.plural||num==='Sg.')});if(!keys.length)continue;const k=pick(keys,r),f=nn.forms[k];
   const sols=[...new Set(Object.keys(nn.forms).filter(x=>norm(nn.forms[x])===norm(f)).flatMap(x=>{const [c,num]=x.split(' ');return nn.genus.map(g=>formOf(c,num,g))}).filter(Boolean))];if(!sols.length)continue;
   if(out.some(y=>norm(y.p)===norm(f)))continue;out.push({...inpItem(f,[shown?shown+' →':'→'],[sols]),ti})}
  return out}
 /* ---------- Verben ---------- */
 const TOPIC={praes:{t:['praes'],v:'a',m:'i'},perf:{t:['perf'],v:'a',m:'i'},impf:{t:['impf'],v:'a',m:'i'},fut:{t:['fut'],v:'a',m:'i'},plqpf:{t:['plqpf'],v:'a',m:'i'},pass:{t:['praes','impf','fut'],v:'p',m:'i'},passperf:{t:['perf','plqpf'],v:'p',m:'i'},konjimpf:{t:['impf','plqpf'],v:'a',m:'k'},konjpraes:{t:['praes'],v:'a',m:'k'},konjperf:{t:['perf'],v:'a',m:'k'}};
 const PERS=['1. Sg.','2. Sg.','3. Sg.','1. Pl.','2. Pl.','3. Pl.'];
 function verbGen(kind,arg,lesson,L){let pool,tp,lab;
  const allowed=m=>L.tenses.has(m.t)&&(m.v==='a'||(m.t==='perf'||m.t==='plqpf'?L.passPerf:L.passive))&&(m.m==='i'||L.konjT.has(m.t))&&L.persons.has(m.p);
  if(kind==='irr'){const [inf,info]=arg.split('|');const v=V().verbParadigm(inf,info||'');if(!v)return null;pool=[{...v,lemma:inf}];lab=inf;const ts=['praes','impf','fut','perf','plqpf'].filter(t=>L.tenses.has(t)&&Object.values(v.meta).some(m=>m.t===t&&m.v==='a'&&m.m==='i'));tp={t:ts.length?ts:['praes'],v:'a',m:'i'}}
  else{tp=TOPIC[arg];if(!tp)return null;lab=tp.t.map(t=>TNAME[t]).join(', ')+(tp.v==='p'?' Passiv':'')+(tp.m==='k'?' Konjunktiv':'');pool=verbPool(lesson,v=>Object.values(v.meta||{}).some(m=>tp.t.includes(m.t)&&m.v===tp.v&&m.m===tp.m))}
  if(!pool.length)return null;
  const isT=m=>tp.t.includes(m.t)&&m.v===tp.v&&m.m===tp.m&&(!m.g||m.g==='m')&&L.persons.has(m.p);
  const dims=()=>{const d=[['Person',['1.','2.','3.']],['Numerus',['Sg.','Pl.']],['Tempus',['praes','impf','fut','perf','plqpf'].filter(t=>L.tenses.has(t)).map(t=>TNAME[t])]];if(L.konj)d.push(['Modus',['Ind.','Konj.']]);if(L.passive)d.push(['Genus verbi',['Akt.','Pass.']]);return d};
  const ana=m=>{const a=[String(m.p%3+1)+'.',m.p<3?'Sg.':'Pl.',TNAME[m.t]];if(L.konj)a.push(m.m==='k'?'Konj.':'Ind.');if(L.passive)a.push(m.v==='p'?'Pass.':'Akt.');return a};
  const types=[['det','Formen bestimmen',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*30){const v=pick(pool,r),keys=Object.keys(v.forms).filter(k=>allowed(v.meta[k])),tk=keys.filter(k=>isT(v.meta[k]));const k=r()<.7&&tk.length?pick(tk,r):pick(keys,r);if(!k)continue;const f=v.forms[k];if(out.some(y=>norm(y.f)===norm(f)))continue;
     const as=keys.filter(x=>norm(v.forms[x])===norm(f)).map(x=>ana(v.meta[x]));out.push({...detItem(f,dims(),as),ti:'Bestimme die Verbform ('+v.lemma+')'})}return out}],
   ['tempus','Tempus zuordnen',1,(r,n)=>{const out=[];let guard=0;const TS=['praes','impf','fut','perf','plqpf'].filter(t=>L.tenses.has(t));while(out.length<n&&guard++<n*30){const v=pick(pool,r),keys=Object.keys(v.forms).filter(k=>allowed(v.meta[k])&&(!v.meta[k].g||v.meta[k].g==='m'));const want=pick(TS,r),ks=keys.filter(k=>v.meta[k].t===want);const k=pick(ks.length?ks:keys,r);if(!k)continue;const f=v.forms[k];if(out.some(y=>norm(y.f)===norm(f)))continue;
     out.push({...detItem(f,[['Tempus',TS.map(t=>TNAME[t])]],[...new Set(keys.filter(x=>norm(v.forms[x])===norm(f)).map(x=>TNAME[v.meta[x].t]))].map(x=>[x])),ti:'In welchem Tempus steht die Form?'})}return out}],
   ...(kind==='irr'?[]:[['herk','Woher kommt die Form? (Grundform nennen)',1,(r,n)=>herkunft(r,n,pool,v=>Object.keys(v.forms).filter(k=>allowed(v.meta[k])&&(tp.t.includes(v.meta[k].t)||r()<.3)).map(k=>v.forms[k]),'Woher kommt die Verbform?')]]),
   ['tab','Konjugieren',0,r=>{const v=pick(pool,r);const ts=tp.t.filter(t=>Object.values(v.meta).some(m=>m.t===t&&m.v===tp.v&&m.m===tp.m));const rows=PERS.filter((p,i)=>L.persons.has(i));
     return [tabItem('Konjugiere '+v.lemma+(v.sg?', '+v.sg:'')+' – '+ts.map(t=>TNAME[t]).join(', ')+(tp.v==='p'?' Passiv':'')+(tp.m==='k'?' Konjunktiv':''),rows,ts,(row,t)=>{const p=PERS.indexOf(row);const k=Object.keys(v.meta).find(x=>{const m=v.meta[x];return m.p===p&&m.t===t&&m.v===tp.v&&m.m===tp.m&&(!m.g||m.g==='m')});return k?v.forms[k]:null},{r,noHalf:true,colLabel:t=>TNAME[t]})]}]];
  if(kind!=='irr')types.splice(types.length-1,0,['conv','Formen umwandeln',1,(r,n)=>{const out=[];let guard=0;while(out.length<n&&guard++<n*40){const v=pick(pool,r),tk=Object.keys(v.forms).filter(k=>isT(v.meta[k]));if(!tk.length)continue;const k=pick(tk,r),m=v.meta[k];
     /* Ausgangsform: gleiche Person, anderes Tempus/Genus/Modus (bei Präsens: anderer Numerus) */
     const src=Object.keys(v.forms).filter(x=>{const s=v.meta[x];if(!allowed(s)||(s.g&&s.g!=='m'))return false;if(tp.t.length===1&&tp.t[0]==='praes'&&tp.v==='a'&&tp.m==='i')return s.t==='praes'&&s.v==='a'&&s.m==='i'&&s.p===(m.p+3)%6;return s.p===m.p&&((s.t!==m.t)+(s.v!==m.v)+(s.m!==m.m))===1});if(!src.length)continue;const sk=pick(src,r),sf=v.forms[sk],s=v.meta[sk];
     if(out.some(y=>norm(y.p)===norm(sf)))continue;
     const want=(tp.t.length===1&&tp.t[0]==='praes'&&tp.m==='i'&&tp.v==='a')?(m.p<3?'Singular':'Plural'):[s.t!==m.t?TNAME[m.t]:'',s.v!==m.v?(m.v==='p'?'Passiv':'Aktiv'):'',s.m!==m.m?(m.m==='k'?'Konjunktiv':'Indikativ'):''].filter(Boolean).join(', ');
     const sols=Object.keys(v.forms).filter(x=>{const q=v.meta[x];return q.p===m.p&&q.t===m.t&&q.v===m.v&&q.m===m.m}).map(x=>v.forms[x]);
     out.push({...inpItem(sf,['→ '+want],[sols]),ti:'Wandle die Form um ('+v.lemma+')'})}return out}]);
  return {label:lab,types}}
 /* ---------- Bewertung ---------- */
 function grade(it,a){a=a||{};
  if(it.k==='tab'){let p=0,max=0,miss=[];it.sol.forEach((row,ri)=>row.forEach((f,ci)=>{if(!f||it.gv[ri][ci])return;const w=it.hf[ri][ci]?.5:1;max+=w;const v=a.c?.[ri]?.[ci]||'';if(f.split('/').some(x=>norm(x)===norm(v))&&norm(v))p+=w;else miss.push(it.rw[ri]+(it.cl.length>1?' '+it.cl[ci]:''))}));return {p,max,note:miss.length?'falsch/leer: '+miss.slice(0,6).join(', ')+(miss.length>6?' …':''):''}}
  if(it.k==='det'){const sel=a.d||[];const best=Math.max(0,...it.sol.map(s=>s.reduce((n,v,i)=>n+(sel[i]===v?1:0),0)));return {p:best,max:it.d.length,note:best<it.d.length?'gewählt: '+sel.map(x=>x||'—').join(' '):''}}
  if(it.k==='inp'){let p=0;const vals=a.v||[];it.sol.forEach((acc,i)=>{if(norm(vals[i])&&acc.some(x=>norm(x)===norm(vals[i])))p++});return {p,max:it.sub.length,note:p<it.sub.length?'„'+vals.join(' | ')+'“':''}}
  return {p:0,max:0}}
 /* Schülerseite bekommt keine Lösungen */
 const studentPart=it=>it.k==='tab'?{k:'tab',ti:it.ti,rw:it.rw,cl:it.cl,gv:it.sol.map((row,ri)=>row.map((f,ci)=>f==null?0:it.gv[ri][ci]?f:''))}:it.k==='det'?{k:'det',ti:it.ti,f:it.f,d:it.d}:{k:'inp',ti:it.ti,p:it.p,sub:it.sub};
 const solText=it=>it.k==='tab'?'':it.k==='det'?it.sol.map(s=>s.join(' ')).join(' · oder · '):it.sol.map(a=>a[0]).join(' · ');
 window.classroomGrammar={gen,grade,pts,studentPart,solText,rngOf,norm};
})();
;

