  dlg.querySelector('[data-lprint]')?.addEventListener('click',()=>{const w=window.open('','_blank');if(!w)return;const W2=rows.filter(r=>subs[r.key]);
   w.document.write('<!doctype html><meta charset="utf-8"><title>'+esc(U.title)+' – Antworten</title><style>body{font:11pt/1.45 -apple-system,Inter,sans-serif;padding:12mm}h1{font-size:16pt}h2{font-size:12.5pt;margin:16px 0 4px;border-bottom:1px solid #ccc}p{margin:3px 0 8px}b{display:inline-block;min-width:110px}</style><h1>'+esc(U.title)+' · '+esc(leCls())+' – Antworten</h1>'+AL.map(([k,l])=>{const g=W2.filter(r=>String(subs[r.key].w?.[k]||'').trim());return g.length?'<h2>'+esc(l)+'</h2>'+g.map(r=>'<p><b>'+esc(r.disp)+'</b> '+esc(subs[r.key].w[k]).replace(/\n/g,'<br>')+'</p>').join(''):''}).join('')+'<scr'+'ipt>setTimeout(print,300)</scr'+'ipt>');w.document.close()});
