  dlg.querySelector('[data-lgr]').onclick=()=>leGradeSetup(u,sel);dlg.querySelector('[data-lpres]')?.addEventListener('click',()=>lePresent(u));dlg.querySelector('[data-lnot]')?.addEventListener('click',()=>leToNotes(u,rows.map(r=>({name:r.key,m:subs[r.key]?mark(subs[r.key]):null})).filter(x=>x.m&&x.m.i),RT,sel));
