/* ==== noten/page-print.js ==== */
// Print the visible page directly, including its current compact display.
(()=>{
 function printPage(panel){
  showExportDialog();const dialog=document.getElementById('exportDialog');dialog.classList.add('single-page-export');document.getElementById('exportTitle').textContent='Seite drucken / exportieren';dialog.querySelector('form>p').textContent=(panel.querySelector('h2')?.textContent||'Aktuelle Seite')+(panel.querySelector('.test-detail-topic input')?.value?' · '+panel.querySelector('.test-detail-topic input').value:'');
  const pageKey=panel.dataset.customPanel;for(const input of dialog.querySelectorAll('[data-export-page]'))input.checked=input.dataset.exportPage===pageKey;
  if(pageKey&&!dialog.querySelector('[data-export-page="'+CSS.escape(pageKey)+'"]')){const row=document.createElement('label');row.className='export-option';const input=document.createElement('input');input.type='checkbox';input.dataset.exportPage=pageKey;input.checked=true;const span=document.createElement('span');span.textContent=(panel.querySelector('h2')?.textContent||'Aktuelle Seite')+(panel.querySelector('.test-detail-topic input')?.value?' · '+panel.querySelector('.test-detail-topic input').value:'');row.append(input,span);document.getElementById('customExportOptions').append(row)}
  document.getElementById('confirmExport').textContent='Drucken / Exportieren';updateTaskExportOptions();updateExportFormat();
 }
 window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-single-page');document.getElementById('pagePrintRoot')?.remove()});
 function add(){for(const panel of document.querySelectorAll('.panel')){if(panel.matches('.exam-combined-page')){panel.querySelector(':scope > .section-title [data-page-print]')?.remove();continue}if(!panel.querySelector('table'))continue;const heading=panel.querySelector('.section-title');if(!heading)continue;let display=heading.querySelector('.oral-display-actions');if(!display){display=document.createElement('div');display.className='oral-display-actions';heading.append(display)}/* 10.49: Drucken gehört zu den Aktionen (untere Zeile, eckig) */const home=(getComputedStyle(display).display!=='none'&&display.parentElement?.querySelector(':scope>.task-actions,:scope>.semester-table-tools,:scope>.custom-heading-controls'))||display;const existing=panel.querySelector('[data-page-print]');if(existing){if(home&&existing.parentElement!==home)home.append(existing);continue}const b=document.createElement('button');b.type='button';b.className='page-print-button';b.dataset.pagePrint='';b.textContent='Drucken';b.onclick=()=>printPage(panel);(home||heading.querySelector('.oral-display-actions')||heading.querySelector('.task-actions,.semester-table-tools')||heading).append(b)}}
 /* 9.75: über den gemeinsamen Beobachter (gebündelt einmal je Bild statt bei jeder Einzeländerung) */
 if(typeof classroomOnDomChange==='function'){add();classroomOnDomChange(add)}else{const observer=new MutationObserver(()=>{observer.disconnect();add();watch()});function watch(){observer.observe(document.querySelector('main')||document.body,{childList:true,subtree:true})}add();watch()}
})();
;

