 const LOCK_BLOCK='.exam-task-add,.exam-task-add-bar,.task-remove,[data-task-action="remove-task"],[data-task-action="add-student"],[data-task-action="add-task"],[data-task-action="remove-student"],[data-task-action="clear-grades"],[data-assessment-import],[data-tproxy="add-student"],[data-tproxy="import"],[data-tclear],.ng-badge button,.test-defaults-badge button,.ng-mode button,.tsl-mode button,.tsl-handle,.test-ab-toggle,.exam-task-card button,.exam-task-card select,.exam-task-card input';
