  const heads=[...(table.tHead?.rows[0]?.cells||[])].map(c=>c.textContent.trim());const rows=[...body.rows].filter(r=>r.cells.length>=2).map(r=>[r.cells[0].textContent.replace(/\s+/g,' ').trim(),r.cells[1].textContent.trim(),!!r.cells[1].querySelector('.grade-four-fail'),(r.cells[1].querySelector('.grade')?.className.match(/\bg[1-6]\b/)||[''])[0]]);if(!rows.length)return;
  const half=Math.ceil(rows.length/2),tbl=list=>'<div class="ng-frame"><table class="ng-plain"><thead><tr><th>'+htmlEscape(heads[0]||'Rohpunkte')+'</th><th>'+htmlEscape(heads[1]||'Note')+'</th></tr></thead><tbody>'+list.map(r=>'<tr><td>'+htmlEscape(r[0])+'</td><td class="ng-grade">'+(r[2]?'<span class="grade g4 grade-four-fail ng-fail" title="4 Punkte: nicht bestanden">'+htmlEscape(r[1])+'</span>':r[3]?'<span class="grade '+r[3]+' ng-fail">'+htmlEscape(r[1])+'</span>':htmlEscape(r[1]))/* 9.46: alle Notenpunkte farbig, nicht nur die 4 */+'</td></tr>').join('')+'</tbody></table></div>';
