/* ==== noten/exam-terminology.js ==== */
// Assessment terminology follows the class setting, independently of a test's input mode.
(()=>{
 const originalText=new WeakMap();
 function terms(){const item=classesBySubject[currentSubject]?.find(c=>c.id===currentClassId),points=classGradingSystem(item)==='gradePoints';return {singular:points?'Klausur':'Klassenarbeit',plural:points?'Klausuren':'Klassenarbeiten'}}
 function updateGroups(){let changed=false;for(const items of Object.values(classesBySubject))for(const item of items){const noun=classGradingSystem(item)==='gradePoints'?'Klausur':'Klassenarbeit',exams=(item.examGroups||[]).filter(g=>!['halfYear','schoolYear','performance','tests','homework','semester','quarterSummary'].includes(g.type));for(const g of exams){const match=String(g.label||'').match(/^(?:(?:Klausur|Klassenarbeit)(?:\s+(\d+))?|(\d+)\. (?:Klassenarbeit|Klausur))$/);if(match){const siblings=exams.filter(e=>e.halfYearId===g.halfYearId),number=match[1]||match[2]||String(siblings.indexOf(g)+1),name=siblings.length===1?noun:number+'. '+noun;if(g.label!==name){g.label=name;changed=true}}}}if(changed)persistClasses()}
 function replaceText(text){const t=terms();return text.replace(/Klassenarbeiten|Klausuren/g,t.plural).replace(/Klassenarbeit|Klausur/g,t.singular).replace(/(Klassenarbeit|Klausur) (\d+)\b/g,'$2. $1')}
 /* 9.75: Bei Änderungen nur die neu hinzugekommenen Teile prüfen statt jedes Mal das ganze Dokument (spürbar am iPhone). */
 const SEL='button,h2,h3,p,legend,summary,th,label';
 /* 11.07: Elemente ohne die Wörter überspringen – auch eine bereits ersetzte Ausgabe enthält sie immer */
 const HAS=/Klausur|Klassenarbeit/;
 function fix(element){if(!HAS.test(element.textContent)||element.closest('.subject-grade-dialog'))return;for(const node of element.childNodes){if(node.nodeType!==Node.TEXT_NODE)continue;const prev=originalText.get(node),source=prev&&node.textContent===prev.output?prev.source:node.textContent;if(!prev&&!/Klausur|Klassenarbeit/.test(source))continue;const output=replaceText(source);if(output!==node.textContent)node.textContent=output;originalText.set(node,{source,output})}for(const attr of ['title','aria-label']){const value=element.getAttribute(attr);if(value&&/Klausur|Klassenarbeit/.test(value)){const v=replaceText(value);if(v!==value)element.setAttribute(attr,v)}}}
 function addQuick(){const add=document.getElementById('addExamQuick');if(add){const label='＋ '+terms().singular,title=terms().singular+' hinzufügen';/* Nur bei Änderung schreiben – sonst löst jede Zuweisung andere Beobachter aus (Endlosschleife mit der Kompaktansicht). */if(add.textContent!==label)add.textContent=label;if(add.title!==title)add.title=title}}
 let lastNoun='';
 function paint(){observer.disconnect();updateGroups();try{lastNoun=terms().singular}catch{}for(const element of document.querySelectorAll(SEL))fix(element);addQuick();watch()}
 function paintSome(records){let noun='';try{noun=terms().singular}catch{}if(noun!==lastNoun){paint();return}observer.disconnect();updateGroups();const seen=new Set();const visit=el=>{if(!el||seen.has(el))return;seen.add(el);fix(el)};
  for(const r of records){const n=r.type==='characterData'?r.target.parentElement:r.target;const roots=r.type==='childList'?[...r.addedNodes].map(x=>x.nodeType===1?x:x.parentElement):[n];
   for(const root of roots){if(!root||!root.isConnected||!HAS.test(root.textContent))continue;visit(root.closest?.(SEL));if(root.querySelectorAll)for(const el of root.querySelectorAll(SEL))visit(el)}
   if(r.type==='childList'){const c=r.target.closest?.(SEL);if(c)visit(c)}}
  addQuick();watch()}
 const observer=new MutationObserver(paintSome);function watch(){observer.observe(document.body,{childList:true,subtree:true,characterData:true})}
 classroomHooks.add('refreshExamNavigation','exam-terminology: Bezeichnungen',{before(){updateGroups()},after(){paint()}});
 paint();
})();
;

/* ==== button-help.js ==== */
// Native hover hints shared by the app and both managers, including dynamic buttons.
(()=>{
 const byId={
  editClassesQuick:'Klassennamen und das Notensystem (Noten oder Notenpunkte) bearbeiten.',
  classroomBackupButton:'Alle App-Daten als Backup sichern oder aus einem Backup wiederherstellen.',
  classroomExportBackup:'Ein vollständiges Backup der Klassen, Eintragungen und Sitzpläne speichern.',
  classroomImportBackup:'Ein gespeichertes Backup auswählen und die App-Daten wiederherstellen.',
  randomStudentButton:'Eine anwesende Person aus der aktuellen Klasse zufällig auswählen und im Sitzplan hervorheben.',
  studentSearchToggle:'Das Suchfeld öffnen, um eine Person im Sitzplan zu finden.',
  classroomStartButton:'Die Personen nach den eingestellten Regeln auf die vorhandenen Plätze verteilen.',
  classroomResetButton:'Die Bewertungen und Hausaufgabeneinträge des ausgewählten Datums zurücksetzen; Namen und Sitzplan bleiben erhalten.',
  applyLayoutButton:'Die ausgewählte Tischanordnung oder Gruppenvorlage auf den Sitzplan anwenden.',
  resetApp:'Alle App-Daten nach Bestätigung zurücksetzen.',
  tabNoten:'Den Noten-Manager öffnen.',tabSitzplan:'Den Unterrichts-Manager öffnen.'
 };
 function hint(button){
  const text=(button.textContent||'').replace(/\u00ad/g,'').replace(/\s+/g,' ').trim(),plain=text.replace(/^[＋+−–-]\s*/,''),remove=/^[−–-]/.test(text);
  if(byId[button.id])return byId[button.id];
  if(button.matches('[data-exam-topic-edit]'))return remove?'Das Klausurthema aus der Überschrift entfernen.':'Ein Klausurthema eingeben und neben „Ergebnisse“ anzeigen.';
  // Keep existing, detailed hints such as the active layout-picker return action.
  if(button.title&&!button.dataset.buttonHelp)return button.title;
  if(button.matches('[role=tab],.subject-tab,.page-tab'))return '„'+text+'“ öffnen.';
  if(button.matches('.classroom-rating-choice')){/* 10.82: Zeichen sind Grafiken – Text aus data-rating-symbol */const sym=(button.dataset.ratingSymbol||text||'').trim();return !sym||sym==='∅'?'Die mündliche Bewertung für diese Person und dieses Datum leeren.':'Die mündliche Mitarbeit mit „'+sym+'“ bewerten.'}
  if(button.matches('[data-zoom-minus]'))return 'Den Sitzplan verkleinern.';
  if(button.matches('[data-zoom-plus]'))return 'Den Sitzplan vergrößern.';
  if(button.matches('[data-zoom-fit]'))return 'Den Sitzplan an die verfügbare Breite anpassen.';
  if(button.matches('[data-zoom-reset]'))return 'Den Sitzplan in Originalgröße (100 %) anzeigen.';
  const exact={
   Drucken:'Druck- und Exportoptionen für diese Seite öffnen.',
   Backup:'App-Daten sichern oder ein Backup wiederherstellen.',
   Rückgängig:'Die letzte Änderung rückgängig machen.',
   'Eingaben löschen':'Die Eintragungen dieser Seite nach Bestätigung löschen.',
   Notenspiegel:'Die Verteilung der Ergebnisse dieser Seite anzeigen.',
   'Text kopieren':'Den angezeigten Text kopieren und das Fenster schließen.',
   'Version löschen':'Nur die ausgewählte gespeicherte Sitzplanversion löschen; die aktuelle Anordnung bleibt bestehen.',
   'Tag bereinigen':'Zwischenstände dieses Tages entfernen; der letzte Sitzplan und alle Gruppeneinteilungen bleiben erhalten.',
   'Vorlage speichern':'Die aktuelle Tischanordnung als eigene Vorlage speichern.',
   Schülerperspektive:'Den Sitzplan aus Sicht der Schülerinnen und Schüler anzeigen.',
   Lehrerperspektive:'Den Sitzplan aus Sicht der Lehrkraft anzeigen.',
   Vollbild:'Den Sitzplan im Vollbild anzeigen oder das Vollbild verlassen.',
   'Neue Zeile':'Eine weitere Eingabezeile in dieser Liste hinzufügen.',
   'Anker löschen':'Entfernt nur die festen Platzzuweisungen im aktuellen Raum. Namen, Bewertungen und Sitzordnung bleiben erhalten.',
   'Alle löschen':'Alle Einträge dieser Liste nach Bestätigung entfernen.',
   Abbrechen:'Dieses Fenster schließen, ohne die Änderungen zu übernehmen.',
   Schließen:'Dieses Fenster schließen.',
   Speichern:'Die Änderungen übernehmen und speichern.',
   OK:'Die Eingaben übernehmen und das Fenster schließen.',
   'Namen hinzufügen':'Die eingetragenen Namen zur aktuellen Klasse hinzufügen.',
   'Klasse hinzufügen':'Die Klasse mit den eingetragenen Namen und Einstellungen anlegen.',
   'Hausaufgabe fehlt':'Für diese Person am ausgewählten Datum eine fehlende Hausaufgabe eintragen oder den Eintrag zurücknehmen.',
   Start:'Die Sitzplätze nach den eingestellten Verteilungsregeln vergeben.'
  };
  if(exact[text])return exact[text];
  if(text==='+'||text==='＋')return 'Eine weitere Spalte hinzufügen.';
  if(/^[＋+]/.test(text))return ({'Schüler:in':'Eine Person zur aktuellen Klasse hinzufügen.',Geschlecht:'Das Geschlecht der Personen dieser Klasse manuell festlegen.',Import:'Namen, Bewertungen und Hausaufgaben aus einer Datei oder eingefügten Tabelle übernehmen.',Klasse:'Eine Klasse oder einen Kurs mit Namensliste und Notensystem anlegen.',Fach:'Ein weiteres Fach anlegen.',Halbjahr:'Ein weiteres Halbjahr anlegen.',Quartal:'Ein neues, leeres Quartal anlegen.',Klausur:'Eine weitere Klausur für das aktuelle Quartal anlegen.',Thema:'Ein Klausurthema eingeben.',Teilnoten:'Teilnoten für die Klausurergebnisse einblenden.'})[plain]||'„'+plain+'“ hinzufügen.';
  if(remove&&plain)return '„'+plain+'“ entfernen.';
  if(text==='−'||text==='–'||text==='-')return 'Diesen Eintrag entfernen.';
  if(text==='+'||text==='＋')return 'Eine weitere Spalte hinzufügen.';
  if(/importieren/i.test(text))return 'Eine Datei auswählen und deren Daten übernehmen.';
  if(/exportieren/i.test(text))return 'Die gewählten Daten als Datei speichern.';
  if(text==='Zurücksetzen')return 'Die zugehörigen Eingaben auf den Ausgangszustand zurücksetzen.';
  // Einträge mit „…“ öffnen erst ein Fenster – nicht „… ausführen“ anhängen.
  if(/…$/.test(text))return button.getAttribute('aria-label')||('„'+text.replace(/\s*…$/,'')+'“ – öffnet ein Fenster mit weiteren Angaben.');
  return button.getAttribute('aria-label')||('„'+text+'“ ausführen.');
 }
 function update(button){const value=hint(button);if(value&&button.title!==value){button.title=value;button.dataset.buttonHelp='true'}}
 function scan(root){if(!root||(root.nodeType!==1&&root!==document))return;if(root.matches?.('button,[role=button]'))update(root);root.querySelectorAll?.('button,[role=button]').forEach(update)}
 scan(document);
 let queue=new Set(),planned=false;new MutationObserver(records=>{for(const record of records){if(record.type==='characterData'){const b=record.target.parentElement?.closest?.('button,[role=button]');if(b)queue.add(b)}else{const b=record.target.closest?.('button,[role=button]');if(b)queue.add(b);for(const node of record.addedNodes)if(node.nodeType===1)queue.add(node)}}if(!planned&&queue.size){planned=true;requestAnimationFrame(()=>{planned=false;const q=queue;queue=new Set();for(const n of q)if(n.isConnected)scan(n)})}}).observe(document.body,{childList:true,subtree:true,characterData:true});
 document.addEventListener('pointerover',event=>{const button=event.target.closest('button,[role=button]');if(button)update(button)},true);
})();
;

/* ==== decimal-display.js ==== */
// Localize plain displayed decimal values without changing stored numbers or inputs.
(()=>{
 function scan(root){if(!root||root.nodeType!==1)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){/* 9.75: erst der schnelle Zahlentest, dann die teure Prüfung der Umgebung */const value=node.textContent;if(!/^\s*[+−-]?\d+\.\d+\s*(?:%|Punkte)?\s*$/.test(value))continue;if(node.parentElement.closest('script,style,textarea,input,[contenteditable=true],[data-app-version],[data-app-version-copy],[data-no-decimal]'))continue;node.textContent=value.replace(/(\d)\.(\d)/,'$1,$2')}}
 const observer=new MutationObserver(records=>{observer.disconnect();for(const r of records){if(r.type==='characterData')scan(r.target.parentElement);else for(const node of r.addedNodes)scan(node.nodeType===1?node:node.parentElement)}watch()});function watch(){observer.observe(document.body,{childList:true,subtree:true,characterData:true})}scan(document.body);watch();
})();
;

/* ==== noten/previous-quarter.js ==== */
// Read-only comparison with the first quarter; current-quarter calculations stay separate.
(()=>{
 const quarterly=new Set(['performance','homework','tests']);
 let refreshing=false,pending=false;
 const originalTableStyles=new WeakMap();
 function clearInline(root=document){root.querySelectorAll('[data-previous-quarter-cell]').forEach(e=>e.remove());root.querySelectorAll('.previous-quarter-inline').forEach(table=>{table.classList.remove('previous-quarter-inline');const old=originalTableStyles.get(table);if(old===null)table.removeAttribute('style');else if(old!==undefined)table.setAttribute('style',old);originalTableStyles.delete(table)})}

 function context(){
  const holder=(classesBySubject[currentSubject]||[]).find(c=>c.id===currentClassId)||subjectPageSource(currentSubject);
  if(Number(holder?.sharedQuarterSelection?.[currentHalfYearId])!==1)return null;
  const groups=subjectExamGroups(currentSubject),group=groups.find(g=>g.pages.includes(activePage));
  if(!group||['halfYear','schoolYear','semester'].includes(group.type))return null;
  /* 9.85: Klassenarbeiten und Klausuren gelten fürs ganze Halbjahr – „1. Quartal“ würde nur dieselben Werte noch einmal zeigen */if(!quarterly.has(group.type)&&group.type!=='quarterSummary')return null;/* Halbjahresnote enthält Q1 und Q2 bereits – kein Vergleichsschalter. */
  const panel=document.querySelector(`[data-custom-panel="${CSS.escape(activePage)}"]`);
  const root=panel?.closest('[data-exam-combined]')||panel;
  if(!root||root.classList.contains('hide'))return null;
  return {holder,groups,group,root,key:['classroom-previous-quarter',currentSubject,currentClassId,currentHalfYearId,group.type,!!group.material].join(':')};
 }
 function readonlyTable(table){
  const clone=table.cloneNode(true);
  clone.querySelectorAll('th .mean-seg:not(.seg-toggle)').forEach(seg=>seg.closest('th')?.classList.add('pq-mean-col'));/* 9.27: Mittelwert-Spalte merken – sie bekommt einen eigenen Schalter */
  clone.querySelectorAll('button,.toggle,.test-mean-slider,.mean-seg,.task-weight-toggle').forEach(e=>e.remove());
  clone.querySelectorAll('input.tov-hidden,input[type=hidden],input[hidden]').forEach(e=>e.remove());/* 10.01: ausgeblendete Felder (gesperrter Test) nicht als Kästen zeigen */
  clone.querySelectorAll('input,select,textarea').forEach(input=>{
   const span=document.createElement('span');span.className=input.className;
   if(input.closest('tbody td')&&!input.closest('.task-student-cell'))span.classList.add('previous-quarter-value');
   span.textContent=input.tagName==='SELECT'?input.selectedOptions[0]?.textContent||'—':input.value||'—';
   if(input.closest('.task-weight-control')&&input.value!==''&&Number.isFinite(Number(input.value)))span.textContent=(Math.trunc((Number(input.value)+1e-10)*100)/100).toLocaleString('de-DE',{maximumFractionDigits:2});
   if(input.type==='date'&&/^\d{4}-\d{2}-\d{2}$/.test(input.value))span.textContent=input.value.split('-').reverse().join('.');
   if(input.classList.contains('task-label-input'))span.textContent=input.value.trim();
   input.replaceWith(span);
  });
  clone.querySelectorAll('*').forEach(e=>{e.removeAttribute('id');for(const a of [...e.attributes])if(a.name.startsWith('data-')||a.name.startsWith('on')||['tabindex','contenteditable'].includes(a.name))e.removeAttribute(a.name)});
  clone.removeAttribute('id');
  clone.querySelectorAll('colgroup,.task-add-column,.task-spacer-column,.task-space-column').forEach(e=>e.remove());
  clone.querySelectorAll('tbody td').forEach(cell=>{if(cell.cellIndex>0&&!cell.querySelector('.previous-quarter-value')){const value=cell.querySelector('.task-end-grade, .compact-cell-value, span');if(value)value.classList.add('previous-quarter-value')}});
  const columns=clone.querySelector('tr')?.children.length||1;
  const widths=document.createElement('colgroup');for(let i=0;i<columns;i++){const col=document.createElement('col');col.style.width=(i===0?230:160)+'px';widths.append(col)}clone.prepend(widths);
  clone.style.setProperty('width',(230+(columns-1)*160)+'px','important');
  return clone;
 }
 function fill(box,c){
  box.replaceChildren();
  const title=document.createElement('h3');title.textContent='1. Quartal – bisherige Eintragungen';box.append(title);
  const matching=quarterly.has(c.group.type)?c.groups.filter(g=>g.id===c.group.id):c.group.type==='quarterSummary'||c.group.type==='semester'?c.groups.filter(g=>g.halfYearId===currentHalfYearId&&!['halfYear','schoolYear','semester','quarterSummary'].includes(g.type)&&classroomQuarterGroupVisible(g,0)):c.groups.filter(g=>g.halfYearId===currentHalfYearId&&!['halfYear','schoolYear','semester','quarterSummary','performance','homework','tests'].includes(g.type)&&classroomQuarterGroupVisible(g,0));
  const old=c.holder.sharedQuarterSelection[currentHalfYearId];
  try{
   c.holder.sharedQuarterSelection[currentHalfYearId]=0;
   if(['quarterSummary','semester'].includes(c.group.type)){
    const summary=c.groups.find(g=>g.type==='quarterSummary'&&g.halfYearId===currentHalfYearId);
    if(summary){const key=summary.pages[0];renderTasksPage(currentSubject,key);const table=document.querySelector(`[data-custom-panel="${CSS.escape(key)}"] table`);if(table)box.append(readonlyTable(table));return;}
   }
   for(const g of matching){
    const keys=quarterly.has(g.type)?[g.pages[0]]:g.pages;
    for(const key of keys){
     if(!key)continue;
     const definition=customPagesFor(currentSubject).find(p=>p.key===key);
     if(g.type==='homework')renderHomeworkPage(currentSubject,key);
     else if(definition?.system==='tasks')renderTasksPage(currentSubject,key);
     else continue;
     const source=document.querySelector(`[data-custom-panel="${CSS.escape(key)}"]`);if(!source)continue;
     const heading=document.createElement('h4');heading.textContent=g.label;box.append(heading);
     for(const table of source.querySelectorAll('table')){const wrap=document.createElement('div');wrap.className='previous-quarter-table';const ro=readonlyTable(table);ro._pqKey=key;wrap.append(ro);box.append(wrap)}
     if(g.type==='performance'&&['quarterSummary','semester'].includes(c.group.type)){
      const students=customPageValues(currentSubject,key).students||[];
      const reviews=document.createElement('table');reviews.className='task-table';
      reviews.innerHTML='<thead><tr><th>Schüler:in</th><th>Selbsteinschätzung · Q1</th><th>Quartalsnote · Q1</th></tr></thead>';
      const body=document.createElement('tbody');
      for(const student of students){const row=document.createElement('tr');for(const value of [student.name,student.quarterReview?.self,student.quarterReview?.teacher]){const cell=document.createElement('td');cell.textContent=value===undefined||value===null||value===''?'—':(value===student.name?String(value):classUsesGradePoints()?formatTaskResult(participationPoints(Number(value))):formatTaskScore(Number(value),'grades',false,true));row.append(cell)}body.append(row)}
      reviews.append(body);const wrap=document.createElement('div');wrap.className='previous-quarter-table';wrap.append(reviews);box.append(wrap);
     }

    }
   }
  }finally{
   c.holder.sharedQuarterSelection[currentHalfYearId]=old;
   if(c.group.type==='quarterSummary')renderTasksPage(currentSubject,c.group.pages[0]);

  }
  if(!box.querySelector('table')){const empty=document.createElement('p');empty.textContent='Für diese Rubrik liegen im 1. Quartal keine Eintragungen vor.';box.append(empty)}
 }
 // Schalter „1. Quartal“ in der oberen Zeile bei den Anzeige-Schaltern (vor „Drucken“; hatching.js ordnet ihn vor „Schraffuren“ ein).
 // 9.27: Schalter der Vergleichsspalte stellt die Darstellung des 1. Quartals um (nur Anzeige)
 document.addEventListener('click',e=>{const b=e.target.closest?.('.pq-mean-seg [data-pq-mean],.pq-mean-seg [data-pq-rounded]');if(!b)return;e.preventDefault();e.stopPropagation();const key=b.closest('.pq-mean-seg').dataset.pqKey,d=taskPageData(currentSubject,key);if(b.dataset.pqMean!==undefined)d.meanDisplay=b.dataset.pqMean;else d.resultRounded=b.dataset.pqRounded==='1';saveCurrentSubject();const c=context();if(c)merge(c)},true);
 function placeButton(c,button){
  const print=c.root.querySelector('.section-title .page-print-button'),row1=print?.closest('.section-title')?.querySelector(':scope>.oral-display-actions');
  if(row1){if(button.parentElement!==row1)row1.append(button)}else if(print)print.before(button);else (c.root.querySelector('.section-title')||c.root).append(button);
 }
 function refresh(){
  if(refreshing)return;refreshing=true;
  try{
   const c=context();
   document.querySelectorAll('[data-previous-quarter-button]').forEach(b=>{if(!c||b.dataset.previousQuarterButton!==c.key)b.remove()});
   document.querySelectorAll('[data-previous-quarter-box]').forEach(b=>{if(!c||b.dataset.previousQuarterBox!==c.key)b.remove()});
   if(!c){clearInline();return;}
   const heading=c.root.querySelector('.section-title')||c.root;
   let button=c.root.querySelector('[data-previous-quarter-button]');
   if(!button){button=document.createElement('label');button.className='toggle previous-quarter-toggle';button.dataset.previousQuarterButton=c.key;button.title='Eintragungen aus dem 1. Quartal zum Vergleich ein- oder ausblenden. Die aktuellen Berechnungen bleiben unverändert.';
    const input=document.createElement('input');input.type='checkbox';input.setAttribute('role','switch');const caption=document.createElement('span');caption.textContent='1. Quartal';caption.dataset.q='Q1';button.append(input,caption);input.setAttribute('aria-label','1. Quartal ein- oder ausblenden');
    placeButton(c,button);
    input.addEventListener('change',()=>{const open=input.checked;localStorage.setItem(c.key,String(open));show(c,button,open)});
    show(c,button,localStorage.getItem(c.key)==='true');
   }else if(button.getAttribute('aria-expanded')==='true'&&!c.root.querySelector('[data-previous-quarter-cell]')){merge(c);}
  }finally{refreshing=false}
 }
 function merge(c){
  clearInline(c.root);
  let target=c.root.querySelector('table');if(!target)return;
  const reference=target.querySelector('tbody td:not(:first-child) .compact-cell-value,tbody td:not(:first-child)>span')||target.querySelector('tbody .task-grade-input,tbody select,tbody .task-end-grade');
  const referenceStyle=reference?getComputedStyle(reference):null;
  const fieldStyle=referenceStyle?Object.fromEntries(['width','min-width','max-width','height','min-height','font-size','font-family','font-weight','border-radius','line-height','padding','margin','border','display','align-items','justify-content','box-sizing'].map(name=>[name,referenceStyle.getPropertyValue(name)])):{};
  const referenceCell=reference?.closest('td');
  const cellStyle=referenceCell?Object.fromEntries(['width','min-width','max-width','padding','border-left','border-right'].map(name=>[name,getComputedStyle(referenceCell).getPropertyValue(name)])):null;
  const comparisonButton=c.root.querySelector('[data-previous-quarter-button]');
  const history=document.createElement('div');fill(history,c);
  if(comparisonButton&&!comparisonButton.isConnected)placeButton(c,comparisonButton);
  target=c.root.querySelector('table');if(!target)return;
  const tables=[...history.querySelectorAll('table')];
  const normalize=value=>String(value||'').trim().toLocaleLowerCase('de-DE');
  const nameOf=row=>normalize(row.cells[0]?.querySelector('input')?.value||row.cells[0]?.textContent);
  const sources=tables.map(table=>({key:table._pqKey,head:table.tHead?.rows[0],rows:new Map([...table.tBodies[0]?.rows||[]].map(row=>[nameOf(row),row]))})).filter(item=>item.head);
  const count=sources.reduce((n,item)=>n+[...item.head.cells].slice(1).filter(c=>!c.classList.contains('quarter-exam-column')).length,0);if(!count){const note=document.createElement('p');note.className='task-score-note previous-quarter-empty';note.dataset.previousQuarterCell='';note.textContent=history.querySelector('p')?.textContent||'Für diese Rubrik liegen im 1. Quartal keine Eintragungen vor.';(target.closest('.table-wrap')||target).before(note);return}
  originalTableStyles.set(target,target.getAttribute('style'));target.classList.add('previous-quarter-inline');
  const colgroup=target.querySelector('colgroup');if(colgroup){const before=colgroup.children[1]||null;for(let i=0;i<count;i++){const col=document.createElement('col');col.dataset.previousQuarterCell='';col.style.width=cellStyle?.width||'46px';colgroup.insertBefore(col,before)}}
  const add=(row,isHead=false)=>{
   const before=row.cells[1]||null,name=nameOf(row);
   for(const source of sources){const from=isHead?source.head:source.rows.get(name);
    for(let i=1;i<source.head.cells.length;i++){
     if(source.head.cells[i]?.classList.contains('quarter-exam-column'))continue;/* Klassenarbeiten/Klausuren gehören zum Halbjahr, nie zu einem Quartal – nicht als „Q1 · …“ wiederholen. */
     const cell=from?.cells[i]?.cloneNode(true)||document.createElement(isHead?'th':'td');
     cell.dataset.previousQuarterCell='';cell.classList.add('previous-quarter-history-cell');
     if(cellStyle)for(const property of isHead?['width','min-width','max-width']:['width','min-width','max-width','padding','border-left','border-right'])cell.style.setProperty(property,cellStyle[property],'important');/* Kopfzellen erhalten keine Seitenränder, sonst erscheint eine zusätzliche senkrechte Linie. */
     for(const field of cell.querySelectorAll('.previous-quarter-value'))for(const [name,value] of Object.entries(fieldStyle)){field.style.setProperty(name,value,'important');if(name==='height')field.style.setProperty('min-height',value,'important')}
     if(target.matches('.compact-entry-table,.quarter-summary-table'))for(const field of cell.querySelectorAll('.previous-quarter-value'))field.style.setProperty('width','auto','important');
     if(!from)cell.textContent='—';
     if(isHead){const caption=cell.querySelector('.compact-heading-label');if(caption)caption.textContent='Q1 · '+caption.textContent;else{const label=document.createElement('small');label.className='previous-quarter-label';label.textContent='1. Quartal';cell.prepend(label)}}
     if(isHead&&source.key&&cell.classList.contains('pq-mean-col'))try{const d=taskPageData(currentSubject,source.key),sys=taskGradeSystem(currentSubject,source.key),w=document.createElement('div');w.innerHTML=taskMeanControl(sys,d).replace(/data-mean-display=/g,'data-pq-mean=').replace(/data-result-rounded=/g,'data-pq-rounded=');const seg=w.firstElementChild;if(seg){seg.classList.add('pq-mean-seg');seg.dataset.pqKey=source.key;cell.append(seg)}}catch(e){console.error(e)}
     row.insertBefore(cell,before);
    }
   }
  };
  if(target.tHead?.rows[0])add(target.tHead.rows[0],true);
  for(const row of [...target.tBodies[0]?.rows||[]])add(row);
  const currentColumns=target.tHead?.rows[0]?.cells.length||count+1;
  target.style.setProperty('min-width',target.matches('.compact-entry-table,.quarter-summary-table')?'0px':(230+count*130+(currentColumns-count-1)*160)+'px','important');

  if(c.group.type==='tests')window.classroomTestsHalfColumn?.(target,'data-previous-quarter-cell');/* 10.04 */
 }

 /* 10.04: Tests – bei eingeblendetem anderen Quartal ganz rechts „Testmittel Q1+Q2“ (Mittel der beiden Quartals-Testmittel; fehlt eines, zählt das vorhandene). Nur Anzeige.
    10.06: mit eigenem Schalter Gerundet | Tendenz | Dezimal (je Klasse gemerkt). */
 const HKEY=()=>'classroom-tests-half-mean:'+currentSubject+':'+currentClassId;
 const hmode=d=>{try{return localStorage.getItem(HKEY())||d?.meanDisplay||'decimal'}catch{return d?.meanDisplay||'decimal'}};
 function paintHalf(root=document){const ctx=window.__testsHalfCtx;if(!ctx)return;const m=hmode(ctx.d),d={...ctx.d,meanDisplay:m};
  for(const sp of root.querySelectorAll('.tests-half-cell [data-v]')){const v=Number(sp.dataset.v);sp.textContent=formatTaskMean(v,ctx.sys,d);if(sp.classList.contains('task-end-grade'))sp.className='task-end-grade '+(taskMeanClass(v,ctx.sys,d)||'')}
  for(const b of root.querySelectorAll('.tests-half-cell [data-half-mean]')){const on=b.dataset.halfMean===m;b.setAttribute('aria-checked',String(on))}}
 if(!window.__testsHalfClick){window.__testsHalfClick=true;document.addEventListener('click',e=>{const b=e.target.closest?.('.tests-half-cell [data-half-mean]');if(!b||b.disabled)return;e.preventDefault();e.stopPropagation();try{localStorage.setItem(HKEY(),b.dataset.halfMean)}catch{}paintHalf()},true)}
 window.classroomTestsHalfColumn=function(target,attr){try{
  const g=subjectExamGroups(currentSubject).find(x=>x.type==='tests'&&x.halfYearId===currentHalfYearId);if(!g||!g.pages?.[0]||!g.pages?.[1]||!target.tHead?.rows[0])return;
  const norm=v=>String(v||'').trim().toLocaleLowerCase('de-DE'),pages=[g.pages[0],g.pages[1]].map(k=>{const d=taskPageData(currentSubject,k),sys=taskGradeSystem(currentSubject,k);return {d,sys,by:new Map((d.students||[]).map(s=>[norm(s.name),s]))}});
  const cur=pages[Number(classesBySubject[currentSubject].find(c=>c.id===currentClassId)?.sharedQuarterSelection?.[currentHalfYearId])===1?1:0];window.__testsHalfCtx={sys:cur.sys,d:cur.d};
  const val=name=>{const v=pages.map(p=>{const s=p.by.get(name);if(!s||!p.d.tasks?.length)return null;try{return taskStudentResult(p.d,s,p.sys==='participation')}catch{return null}}).filter(x=>x!==null&&Number.isFinite(x));return v.length?v.reduce((a,b)=>a+b,0)/v.length:null};
  const mk=(tag,cls)=>{const c=document.createElement(tag);c.setAttribute(attr,'');c.classList.add('tests-half-cell');if(cls)c.className+=' '+cls;return c};
  const th=mk('th');th.innerHTML='<div class="mh-stack"><div class="mh-top"><span class="th-main">Testmittel</span> <small class="previous-quarter-label">Q1 + Q2</small></div></div>';th.title='Mittel der Testmittel aus dem 1. und 2. Quartal – nur zur Ansicht';
  try{const w=document.createElement('div');w.innerHTML=taskMeanControl(cur.sys,{...cur.d,meanDisplay:hmode(cur.d)}).replace(/data-mean-display=/g,'data-half-mean=').replace(/data-result-rounded=/g,'data-half-rounded=');const seg=w.firstElementChild;if(seg){seg.classList.add('tests-half-seg');th.querySelector('.mh-stack').append(seg)}}catch(e){console.warn(e)}
  target.tHead.rows[0].append(th);
  const all=[];for(const row of target.tBodies[0]?.rows||[]){if(row.cells.length<2)continue;const name=norm(row.cells[0]?.querySelector('input')?.value||row.cells[0]?.textContent);const v=val(name);const td=mk('td');
   if(v===null)td.innerHTML='<span class="task-end-grade">—</span>';else{all.push(v);const sp=document.createElement('span');sp.className='task-end-grade';sp.dataset.v=String(v);td.append(sp)}row.append(td)}
  const fr=target.tFoot?.rows[0];if(fr){const td=mk('td');if(all.length){const sp=document.createElement('span');sp.dataset.v=String(all.reduce((a,b)=>a+b,0)/all.length);td.append(sp)}else td.textContent='—';fr.append(td)}
  paintHalf(target);
 }catch(e){console.warn('Testmittel Q1+Q2',e)}};
 if(!document.getElementById('tests-half-style')){const st=document.createElement('style');st.id='tests-half-style';st.textContent='body[data-module=noten] table th.tests-half-cell,body[data-module=noten] table td.tests-half-cell{border-left:3px solid #9fb3ce;background:#f7f9fd;min-width:120px;text-align:center}body[data-module=noten] table th.tests-half-cell .previous-quarter-label{display:block;margin:4px 0 0}body[data-module=noten] table th.tests-half-cell .mh-stack{display:flex;flex-direction:column;align-items:center;row-gap:21px}/* 10.09: gleicher Abstand wie bei „Testmittel · 2. Quartal“ */';document.head.append(st)}
 function show(c,button,open){
  const input=button.querySelector('input');if(input)input.checked=open;button.setAttribute('aria-expanded',String(open));
  c.root.querySelector('[data-previous-quarter-box]')?.remove();clearInline(c.root);
  if(open)merge(c);
 }
 classroomHooks.add('setPage','previous-quarter: Vergleichsschalter',{after(){refresh()}});
 /* 10.95: gemeinsamer Beobachter */if(typeof classroomOnDomChange==='function')classroomOnDomChange(()=>{if(!refreshing)refresh()});else new MutationObserver(()=>{if(pending||refreshing)return;pending=true;requestAnimationFrame(()=>{pending=false;refresh()})}).observe(document.body,{childList:true,subtree:true});
 refresh();
})();
;

/* ==== noten/next-quarter.js ==== */
/* 9.102: Gegenstück zu previous-quarter.js – im 1. Quartal blendet „2. Quartal“ die Eintragungen des 2. Quartals rechts ein (nur Anzeige).
   Erzeugt aus previous-quarter.js; Klassen für Aussehen/Sortierung werden geteilt, Aufräum-Merkmale sind eigene (data-next-quarter-…). */
(()=>{
 const quarterly=new Set(['performance','homework','tests']);
 let refreshing=false,pending=false;
 const originalTableStyles=new WeakMap();
 function clearInline(root=document){root.querySelectorAll('[data-next-quarter-cell]').forEach(e=>e.remove());root.querySelectorAll('.next-quarter-inline').forEach(table=>{table.classList.remove('next-quarter-inline');const old=originalTableStyles.get(table);if(old===null)table.removeAttribute('style');else if(old!==undefined)table.setAttribute('style',old);originalTableStyles.delete(table)})}

 function context(){
  if(document.documentElement.matches('.ph-lite,.cm-quick'))return null;/* Karten (iPhone, Seitenleiste) nutzen die Verlaufsspalten als „1. Quartal“ */
  const holder=(classesBySubject[currentSubject]||[]).find(c=>c.id===currentClassId)||subjectPageSource(currentSubject);
  if(Number(holder?.sharedQuarterSelection?.[currentHalfYearId])!==0)return null;
  const groups=subjectExamGroups(currentSubject),group=groups.find(g=>g.pages.includes(activePage));
  if(!group||['halfYear','schoolYear','semester'].includes(group.type))return null;
  /* 9.85: Klassenarbeiten und Klausuren gelten fürs ganze Halbjahr – „1. Quartal“ würde nur dieselben Werte noch einmal zeigen */if(!quarterly.has(group.type)&&group.type!=='quarterSummary')return null;/* Halbjahresnote enthält Q1 und Q2 bereits – kein Vergleichsschalter. */
  const panel=document.querySelector(`[data-custom-panel="${CSS.escape(activePage)}"]`);
  const root=panel?.closest('[data-exam-combined]')||panel;
  if(!root||root.classList.contains('hide'))return null;
  return {holder,groups,group,root,key:['classroom-next-quarter',currentSubject,currentClassId,currentHalfYearId,group.type,!!group.material].join(':')};
 }
 function readonlyTable(table){
  const clone=table.cloneNode(true);
  clone.querySelectorAll('th .mean-seg:not(.seg-toggle)').forEach(seg=>seg.closest('th')?.classList.add('pq-mean-col'));/* 9.27: Mittelwert-Spalte merken – sie bekommt einen eigenen Schalter */
  clone.querySelectorAll('button,.toggle,.test-mean-slider,.mean-seg,.task-weight-toggle').forEach(e=>e.remove());
  clone.querySelectorAll('input.tov-hidden,input[type=hidden],input[hidden]').forEach(e=>e.remove());/* 10.01: ausgeblendete Felder (gesperrter Test) nicht als Kästen zeigen */
  clone.querySelectorAll('input,select,textarea').forEach(input=>{
   const span=document.createElement('span');span.className=input.className;
   if(input.closest('tbody td')&&!input.closest('.task-student-cell'))span.classList.add('previous-quarter-value');
   span.textContent=input.tagName==='SELECT'?input.selectedOptions[0]?.textContent||'—':input.value||'—';
   if(input.closest('.task-weight-control')&&input.value!==''&&Number.isFinite(Number(input.value)))span.textContent=(Math.trunc((Number(input.value)+1e-10)*100)/100).toLocaleString('de-DE',{maximumFractionDigits:2});
   if(input.type==='date'&&/^\d{4}-\d{2}-\d{2}$/.test(input.value))span.textContent=input.value.split('-').reverse().join('.');
   if(input.classList.contains('task-label-input'))span.textContent=input.value.trim();
   input.replaceWith(span);
  });
  clone.querySelectorAll('*').forEach(e=>{e.removeAttribute('id');for(const a of [...e.attributes])if(a.name.startsWith('data-')||a.name.startsWith('on')||['tabindex','contenteditable'].includes(a.name))e.removeAttribute(a.name)});
  clone.removeAttribute('id');
  clone.querySelectorAll('colgroup,.task-add-column,.task-spacer-column,.task-space-column').forEach(e=>e.remove());
  clone.querySelectorAll('tbody td').forEach(cell=>{if(cell.cellIndex>0&&!cell.querySelector('.previous-quarter-value')){const value=cell.querySelector('.task-end-grade, .compact-cell-value, span');if(value)value.classList.add('previous-quarter-value')}});
  const columns=clone.querySelector('tr')?.children.length||1;
  const widths=document.createElement('colgroup');for(let i=0;i<columns;i++){const col=document.createElement('col');col.style.width=(i===0?230:160)+'px';widths.append(col)}clone.prepend(widths);
  clone.style.setProperty('width',(230+(columns-1)*160)+'px','important');
  return clone;
 }
 function fill(box,c){
  box.replaceChildren();
  const title=document.createElement('h3');title.textContent='2. Quartal – Eintragungen';box.append(title);
  const matching=quarterly.has(c.group.type)?c.groups.filter(g=>g.id===c.group.id):c.group.type==='quarterSummary'||c.group.type==='semester'?c.groups.filter(g=>g.halfYearId===currentHalfYearId&&!['halfYear','schoolYear','semester','quarterSummary'].includes(g.type)&&classroomQuarterGroupVisible(g,1)):c.groups.filter(g=>g.halfYearId===currentHalfYearId&&!['halfYear','schoolYear','semester','quarterSummary','performance','homework','tests'].includes(g.type)&&classroomQuarterGroupVisible(g,1));
  const old=c.holder.sharedQuarterSelection[currentHalfYearId];
  try{
   c.holder.sharedQuarterSelection[currentHalfYearId]=1;
   if(['quarterSummary','semester'].includes(c.group.type)){
    const summary=c.groups.find(g=>g.type==='quarterSummary'&&g.halfYearId===currentHalfYearId);
    if(summary){const key=summary.pages[0];renderTasksPage(currentSubject,key);const table=document.querySelector(`[data-custom-panel="${CSS.escape(key)}"] table`);if(table)box.append(readonlyTable(table));return;}
   }
   for(const g of matching){
    const keys=quarterly.has(g.type)?[g.pages[1]]:g.pages;
    for(const key of keys){
     if(!key)continue;
     const definition=customPagesFor(currentSubject).find(p=>p.key===key);
     if(g.type==='homework')renderHomeworkPage(currentSubject,key);
     else if(definition?.system==='tasks')renderTasksPage(currentSubject,key);
     else continue;
     const source=document.querySelector(`[data-custom-panel="${CSS.escape(key)}"]`);if(!source)continue;
     const heading=document.createElement('h4');heading.textContent=g.label;box.append(heading);
     for(const table of source.querySelectorAll('table')){const wrap=document.createElement('div');wrap.className='previous-quarter-table';const ro=readonlyTable(table);ro._pqKey=key;wrap.append(ro);box.append(wrap)}
     if(g.type==='performance'&&['quarterSummary','semester'].includes(c.group.type)){
      const students=customPageValues(currentSubject,key).students||[];
      const reviews=document.createElement('table');reviews.className='task-table';
      reviews.innerHTML='<thead><tr><th>Schüler:in</th><th>Selbsteinschätzung · Q2</th><th>Quartalsnote · Q2</th></tr></thead>';
      const body=document.createElement('tbody');
      for(const student of students){const row=document.createElement('tr');for(const value of [student.name,student.quarterReview?.self,student.quarterReview?.teacher]){const cell=document.createElement('td');cell.textContent=value===undefined||value===null||value===''?'—':(value===student.name?String(value):classUsesGradePoints()?formatTaskResult(participationPoints(Number(value))):formatTaskScore(Number(value),'grades',false,true));row.append(cell)}body.append(row)}
      reviews.append(body);const wrap=document.createElement('div');wrap.className='previous-quarter-table';wrap.append(reviews);box.append(wrap);
     }

    }
   }
  }finally{
   c.holder.sharedQuarterSelection[currentHalfYearId]=old;
   if(c.group.type==='quarterSummary')renderTasksPage(currentSubject,c.group.pages[0]);

  }
  if(!box.querySelector('table')){const empty=document.createElement('p');empty.textContent='Für diese Rubrik liegen im 2. Quartal noch keine Eintragungen vor.';box.append(empty)}
 }
 // Schalter „1. Quartal“ in der oberen Zeile bei den Anzeige-Schaltern (vor „Drucken“; hatching.js ordnet ihn vor „Schraffuren“ ein).
 // 9.27: Schalter der Vergleichsspalte stellt die Darstellung des 1. Quartals um (nur Anzeige)
 document.addEventListener('click',e=>{const b=e.target.closest?.('.pq-mean-seg [data-pq-mean],.pq-mean-seg [data-pq-rounded]');if(!b)return;e.preventDefault();e.stopPropagation();const key=b.closest('.pq-mean-seg').dataset.pqKey,d=taskPageData(currentSubject,key);if(b.dataset.pqMean!==undefined)d.meanDisplay=b.dataset.pqMean;else d.resultRounded=b.dataset.pqRounded==='1';saveCurrentSubject();const c=context();if(c)merge(c)},true);
 function placeButton(c,button){
  const print=c.root.querySelector('.section-title .page-print-button'),row1=print?.closest('.section-title')?.querySelector(':scope>.oral-display-actions');
  if(row1){if(button.parentElement!==row1)row1.append(button)}else if(print)print.before(button);else (c.root.querySelector('.section-title')||c.root).append(button);
 }
 function refresh(){
  if(refreshing)return;refreshing=true;
  try{
   const c=context();
   document.querySelectorAll('[data-next-quarter-button]').forEach(b=>{if(!c||b.dataset.nextQuarterButton!==c.key)b.remove()});
   document.querySelectorAll('[data-next-quarter-box]').forEach(b=>{if(!c||b.dataset.nextQuarterBox!==c.key)b.remove()});
   if(!c){clearInline();return;}
   const heading=c.root.querySelector('.section-title')||c.root;
   let button=c.root.querySelector('[data-next-quarter-button]');
   if(!button){button=document.createElement('label');button.className='toggle previous-quarter-toggle';button.dataset.nextQuarterButton=c.key;button.title='Eintragungen aus dem 2. Quartal rechts ein- oder ausblenden. Die Berechnungen des 1. Quartals bleiben unverändert.';
    const input=document.createElement('input');input.type='checkbox';input.setAttribute('role','switch');const caption=document.createElement('span');caption.textContent='2. Quartal';caption.dataset.q='Q2';button.append(input,caption);input.setAttribute('aria-label','2. Quartal ein- oder ausblenden');
    placeButton(c,button);
    input.addEventListener('change',()=>{const open=input.checked;localStorage.setItem(c.key,String(open));show(c,button,open)});
    show(c,button,localStorage.getItem(c.key)==='true');
   }else if(button.getAttribute('aria-expanded')==='true'&&!c.root.querySelector('[data-next-quarter-cell]')){merge(c);}
  }finally{refreshing=false}
 }
 function merge(c){
  clearInline(c.root);
  let target=c.root.querySelector('table');if(!target)return;
  const reference=target.querySelector('tbody td:not(:first-child) .compact-cell-value,tbody td:not(:first-child)>span')||target.querySelector('tbody .task-grade-input,tbody select,tbody .task-end-grade');
  const referenceStyle=reference?getComputedStyle(reference):null;
  const fieldStyle=referenceStyle?Object.fromEntries(['width','min-width','max-width','height','min-height','font-size','font-family','font-weight','border-radius','line-height','padding','margin','border','display','align-items','justify-content','box-sizing'].map(name=>[name,referenceStyle.getPropertyValue(name)])):{};
  const referenceCell=reference?.closest('td');
  const cellStyle=referenceCell?Object.fromEntries(['width','min-width','max-width','padding','border-left','border-right'].map(name=>[name,getComputedStyle(referenceCell).getPropertyValue(name)])):null;
  const comparisonButton=c.root.querySelector('[data-next-quarter-button]');
  const history=document.createElement('div');fill(history,c);
  if(comparisonButton&&!comparisonButton.isConnected)placeButton(c,comparisonButton);
  target=c.root.querySelector('table');if(!target)return;
  const tables=[...history.querySelectorAll('table')];
  const normalize=value=>String(value||'').trim().toLocaleLowerCase('de-DE');
  const nameOf=row=>normalize(row.cells[0]?.querySelector('input')?.value||row.cells[0]?.textContent);
  const sources=tables.map(table=>({key:table._pqKey,head:table.tHead?.rows[0],rows:new Map([...table.tBodies[0]?.rows||[]].map(row=>[nameOf(row),row]))})).filter(item=>item.head);
  const count=sources.reduce((n,item)=>n+[...item.head.cells].slice(1).filter(c=>!c.classList.contains('quarter-exam-column')).length,0);if(!count){const note=document.createElement('p');note.className='task-score-note previous-quarter-empty';note.dataset.nextQuarterCell='';note.textContent=history.querySelector('p')?.textContent||'Für diese Rubrik liegen im 2. Quartal noch keine Eintragungen vor.';(target.closest('.table-wrap')||target).before(note);return}
  originalTableStyles.set(target,target.getAttribute('style'));target.classList.add('next-quarter-inline');
  const colgroup=target.querySelector('colgroup');if(colgroup){const before=null;for(let i=0;i<count;i++){const col=document.createElement('col');col.dataset.nextQuarterCell='';col.style.width=cellStyle?.width||'46px';colgroup.insertBefore(col,before)}}
  const add=(row,isHead=false)=>{
   const before=null,name=nameOf(row);/* rechts anhängen */
   for(const source of sources){const from=isHead?source.head:source.rows.get(name);
    for(let i=1;i<source.head.cells.length;i++){
     if(source.head.cells[i]?.classList.contains('quarter-exam-column'))continue;/* Klassenarbeiten/Klausuren gehören zum Halbjahr, nie zu einem Quartal – nicht als „Q1 · …“ wiederholen. */
     const cell=from?.cells[i]?.cloneNode(true)||document.createElement(isHead?'th':'td');
     cell.dataset.nextQuarterCell='';cell.classList.add('previous-quarter-history-cell');
     if(cellStyle)for(const property of isHead?['width','min-width','max-width']:['width','min-width','max-width','padding','border-left','border-right'])cell.style.setProperty(property,cellStyle[property],'important');/* Kopfzellen erhalten keine Seitenränder, sonst erscheint eine zusätzliche senkrechte Linie. */
     for(const field of cell.querySelectorAll('.previous-quarter-value'))for(const [name,value] of Object.entries(fieldStyle)){field.style.setProperty(name,value,'important');if(name==='height')field.style.setProperty('min-height',value,'important')}
     if(target.matches('.compact-entry-table,.quarter-summary-table'))for(const field of cell.querySelectorAll('.previous-quarter-value'))field.style.setProperty('width','auto','important');
     if(!from)cell.textContent='—';
     if(isHead){const caption=cell.querySelector('.compact-heading-label');if(caption)caption.textContent='Q2 · '+caption.textContent;else{const label=document.createElement('small');label.className='previous-quarter-label';label.textContent='2. Quartal';cell.prepend(label)}}
     if(isHead&&source.key&&cell.classList.contains('pq-mean-col'))try{const d=taskPageData(currentSubject,source.key),sys=taskGradeSystem(currentSubject,source.key),w=document.createElement('div');w.innerHTML=taskMeanControl(sys,d).replace(/data-mean-display=/g,'data-pq-mean=').replace(/data-result-rounded=/g,'data-pq-rounded=');const seg=w.firstElementChild;if(seg){seg.classList.add('pq-mean-seg');seg.dataset.pqKey=source.key;cell.append(seg)}}catch(e){console.error(e)}
     row.insertBefore(cell,before);
    }
   }
  };
  if(target.tHead?.rows[0])add(target.tHead.rows[0],true);
  for(const row of [...target.tBodies[0]?.rows||[]])add(row);
  const currentColumns=target.tHead?.rows[0]?.cells.length||count+1;
  target.style.setProperty('min-width',target.matches('.compact-entry-table,.quarter-summary-table')?'0px':(230+count*130+(currentColumns-count-1)*160)+'px','important');

  if(c.group.type==='tests')window.classroomTestsHalfColumn?.(target,'data-next-quarter-cell');/* 10.04 */
 }
 function show(c,button,open){
  const input=button.querySelector('input');if(input)input.checked=open;button.setAttribute('aria-expanded',String(open));
  c.root.querySelector('[data-next-quarter-box]')?.remove();clearInline(c.root);
  if(open)merge(c);
 }
 classroomHooks.add('setPage','next-quarter: Schalter 2. Quartal',{after(){refresh()}});
 /* 10.95: gemeinsamer Beobachter */if(typeof classroomOnDomChange==='function')classroomOnDomChange(()=>{if(!refreshing)refresh()});else new MutationObserver(()=>{if(pending||refreshing)return;pending=true;requestAnimationFrame(()=>{pending=false;refresh()})}).observe(document.body,{childList:true,subtree:true});
 refresh();
 {const st=document.createElement('style');st.textContent='body[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell{width:160px!important;min-width:160px!important;max-width:160px!important;padding:10px 8px!important;box-sizing:border-box;vertical-align:middle;background:#fff}\nbody[data-module=noten] table.next-quarter-inline th.previous-quarter-history-cell{background:#f5f7fc;white-space:normal}\nbody[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell .previous-quarter-value{display:inline-flex!important;align-items:center;justify-content:center;box-sizing:border-box;width:136px!important;min-width:0!important;max-width:100%!important;height:38px!important;min-height:38px!important;margin:0!important;padding:4px 8px!important;border:1px solid #dbe3ef;border-radius:9px;font-size:19px!important;font-weight:700;line-height:1!important;vertical-align:middle}\nbody[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell .task-date-input{display:inline-flex!important;align-items:center;justify-content:center;width:140px!important;max-width:100%!important;height:34px!important;min-height:0!important;font-size:15px!important;padding:4px!important;white-space:nowrap;box-sizing:border-box}\nbody[data-module=noten] table.next-quarter-inline :not(.previous-quarter-history-cell)+.previous-quarter-history-cell{border-left:3px solid #9fb3ce}\nbody[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell{width:130px!important;min-width:130px!important;max-width:130px!important;padding:8px 8px!important}\nbody[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell .previous-quarter-value{width:110px!important}\nbody[data-module=noten] table.next-quarter-inline .previous-quarter-history-cell .task-date-input{width:114px!important;font-size:14px!important}\nbody[data-module=noten] table.compact-entry-table.next-quarter-inline th.previous-quarter-history-cell{background:transparent!important;border:0!important;border-bottom:1px solid var(--line,#dbe3ef)!important;padding:0!important;overflow:visible}';document.head.append(st)}
})();
