/* ==== noten/quarter-dates.js ==== */
// Explicit school-wide period dates; legacy second-quarter boundaries are retained.
function classroomPeriodSettings(){try{return JSON.parse(localStorage.getItem('notenrechner-period-dates')||'{}')}catch{return {}}}
function classroomPeriodKey(year){return String(year?.label||'').trim()}
function classroomPeriodDate(year,kind){const saved=classroomPeriodSettings()[classroomPeriodKey(year)]?.[kind];if(saved!==undefined)return saved;if(kind==='second'){try{return JSON.parse(localStorage.getItem('notenrechner-quarter-boundaries')||'{}')[classroomPeriodKey(year)]||''}catch{}}return ''}
function classroomQuarterPeriodName(year,index){const years=subjectExamGroups(currentSubject).filter(g=>g.type==='halfYear');return `${(years.indexOf(year)===1?2:0)+index+1}. Quartal`}
function classroomQuarterBoundary(year){return classroomPeriodDate(year,'second')}
function classroomQuarterForDate(year,date,fallback=0){const boundary=classroomQuarterBoundary(year);return boundary&&/^\d{4}-\d{2}-\d{2}$/.test(date)?(date>=boundary?1:0):fallback}
function classroomPeriodField(item,row){
 if(!item.periodYear)return;const date=document.createElement('input');date.type='date';date.value=item.pendingDate??classroomPeriodDate(item.periodYear,item.dateKind);date.style.cssText='width:160px;min-width:140px;flex:0 1 160px';date.setAttribute('aria-label','Beginn '+item.value);date.title=item.dateKind==='start'&&item.quarterIndex===0?'Wird vom Beginn des Halbjahres übernommen.':'Beginn dieses Zeitraums';date.readOnly=item.quarterIndex===0;date.oninput=()=>item.pendingDate=date.value;row.append(date);row.style.cssText='display:grid;grid-template-columns:38px minmax(100px,1fr) minmax(140px,180px);gap:10px;align-items:center';const name=row.querySelector('input[type="text"]');name.style.cssText='grid-column:2;grid-row:1;width:100%;min-width:0';date.style.cssText='grid-column:3;grid-row:1;width:100%;min-width:0;box-sizing:border-box';
}
function classroomSavePeriodDates(items){const settings=classroomPeriodSettings();for(const item of items){if(!item.periodYear||item.quarterIndex===0)continue;const key=classroomPeriodKey(item.periodYear),date=item.pendingDate??classroomPeriodDate(item.periodYear,item.dateKind);settings[key]??={};settings[key][item.dateKind]=date}localStorage.setItem('notenrechner-period-dates',JSON.stringify(settings))}
// Route a newly edited oral-assessment column by its date, keeping the whole date together.
function classroomRouteOralTask(pageKey,taskId){
 const item=classesBySubject[currentSubject]?.find(c=>c.id===currentClassId),tracker=item?.examGroups?.find(g=>g.type==='performance'&&g.pages?.includes(pageKey));if(!tracker)return;
 const year=item.examGroups.find(g=>g.id===tracker.halfYearId),data=taskPageData(currentSubject,pageKey),task=data.tasks.find(t=>t.id===taskId);if(!task?.date)return;
 const index=classroomQuarterForDate(year,task.date,tracker.pages.indexOf(pageKey));if(index===tracker.pages.indexOf(pageKey))return;
 const source=subjectPageSource(currentSubject),state=subjectStates[stateScope(currentSubject)];state.customValues??={};source.pages??=[];source.pageNames??={};source.pageSystems??={};
 for(let i=0;i<=index;i++)if(!tracker.pages[i]){let key='tasks-quarter-'+makeTaskId('auto');source.pages.push(key);source.pageNames[key]=`${i+1}. Quartal`;source.pageSystems[key]='participation';tracker.pages[i]=key;state.customValues[key]={tasks:[],students:[],numericParticipation:data.numericParticipation}}
 const target=taskPageData(currentSubject,tracker.pages[index]);let dest=target.tasks.find(t=>t.date===task.date);if(!dest){dest={...task,id:makeTaskId('task')};target.tasks.push(dest)}
 for(const pupil of data.students){let other=target.students.find(s=>s.id===pupil.id);if(!other){other={...pupil,grades:{},rawScores:{},statuses:{}};delete other.quarterReview;target.students.push(other)}other.grades??={};if(pupil.grades?.[task.id]!==undefined&&pupil.grades[task.id]!=='')other.grades[dest.id]=pupil.grades[task.id];delete pupil.grades?.[task.id]}
 data.tasks=data.tasks.filter(t=>t.id!==task.id);rebalanceTaskWeights(data);rebalanceTaskWeights(target);tracker.enabledQuarters??=[];if(!tracker.enabledQuarters.includes(index))tracker.enabledQuarters.push(index);item.sharedQuarterCounts??={};item.sharedQuarterCounts[year.id]=Math.max(index+1,item.sharedQuarterCounts[year.id]||1);item.sharedQuarterSelection??={};item.sharedQuarterSelection[year.id]=index;
 const record=customSubjects.find(s=>s.id===currentSubject);if(record){record.pages=source.pages;record.pageNames={...source.pageNames};record.pageSystems={...source.pageSystems};persistCustomSubjects()}else localStorage.setItem(builtInExtraPagesKey,JSON.stringify(builtInExtraPages));persistClasses();saveCurrentSubject();buildCustomSubjectPanels(currentSubject);refreshExamNavigation();setPage(tracker.pages[index]);
}
const classroomOriginalSaveGrade=saveStudentGrade;
saveStudentGrade=function(input,...args){const page=input.closest('[data-custom-panel]')?.dataset.customPanel,id=input.dataset.taskId,result=classroomOriginalSaveGrade(input,...args);if(page&&!input.validationMessage)classroomRouteOralTask(page,id);return result};

// New tests follow today's configured quarter even while an older quarter is open.
function classroomSelectTestQuarter(){const holder=classesBySubject[currentSubject]?.find(c=>c.id===currentClassId);if(!holder)return 0;const year=subjectExamGroups(currentSubject).find(g=>g.type==='halfYear'&&g.id===currentHalfYearId),date=new Date().toLocaleDateString('sv-SE'),fallback=holder.sharedQuarterSelection?.[currentHalfYearId]||0,index=classroomQuarterForDate(year,date,fallback);holder.sharedQuarterSelection??={};holder.sharedQuarterSelection[currentHalfYearId]=index;holder.sharedQuarterCounts??={};holder.sharedQuarterCounts[currentHalfYearId]=Math.max(index+1,holder.sharedQuarterCounts[currentHalfYearId]||1);persistClasses();return index}
;

/* ==== noten/structure-repair.js ==== */
/* Strukturreparatur beim Start (idempotent):
   1. Doppelte Bereiche „Mündliche Mitarbeit“, „Hausaufgaben“, „Material“ oder „Tests“ im selben Halbjahr werden zusammengeführt,
      sofern sich ihre Quartalsseiten nicht widersprechen.
   2. Verwaiste Seiten mit datierten Eintragungen (z. B. nach versehentlichem Löschen eines doppelten Bereichs) werden wieder
      dem passenden Quartal zugeordnet, wenn dessen Seite noch leer ist.
   3. Quartale mit Eintragungen werden in der Navigation und im Excel-Export immer berücksichtigt. */
(()=>{
 const log=[],where=(subject,item)=>(subjects?.[subject]?.label||subject)+' · '+(item.label||'Klasse');
 const filled=v=>v!==''&&v!==null&&v!==undefined;
 function hasData(data){
  if(!data)return false;
  const items=[...(data.tasks||[]),...(data.assignments||[])];
  const dated=items.some(t=>t?.date);
  const entries=(data.students||[]).some(s=>Object.values(s.grades||{}).some(filled)||Object.values(s.rawScores||{}).some(filled)||Object.values(s.statuses||{}).some(v=>filled(v)&&v!=='done')||filled(s.quarterReview?.teacher));
  return dated&&entries||entries;
 }
 const kindOf=g=>g.type==='homework'?(g.material?'material':'homework'):g.type==='tests'&&g.digital?'digital':g.type;
 const quarterly=['performance','homework','material','tests','digital'];
 function repairClass(subject,item){
  const state=subjectStates[`${subject}::class::${item.id}`],values=state?.customValues;if(!values||!Array.isArray(item.examGroups))return false;
  let changed=false;const groups=item.examGroups,years=groups.filter(g=>g.type==='halfYear');
  /* 10.03: Anteile datierter Spalten (Mitarbeit, Tests) ergeben nicht 100 % – z. B. nach dem Zusammenführen zwei Spalten am selben Tag –
     dann rechnet die App keinen Mittelwert. Nicht bearbeitete Anteile wie in der App gleichmäßig verteilen. */
  try{for(const data of Object.values(values)){const t=data?.tasks;if(!Array.isArray(t)||t.length<2||!t.every(x=>x&&x.date&&'weight' in x)||t.some(x=>x.weightEdited))continue;
   if(typeof taskWeightInfo!=='function'||typeof rebalanceTaskWeights!=='function'||taskWeightInfo(data).valid)continue;const before=t.map(x=>x.weight).join('/');rebalanceTaskWeights(data);
   if(taskWeightInfo(data).valid){changed=true;log.push(where(subject,item)+': Anteile '+before+' % auf '+t.map(x=>String(x.weight).replace('.',',')).join(' / ')+' % verteilt')}}}catch(e){console.warn(e)}
  for(const year of years){
   for(const kind of quarterly){
    const same=groups.filter(g=>kindOf(g)===kind&&g.halfYearId===year.id);
    // 1. Doppelte Bereiche zusammenführen
    if(same.length>1){
     const target=same[0],length=Math.max(...same.map(g=>g.pages?.length||0)),pages=[];let conflict=false;
     for(let q=0;q<length;q++){const candidates=same.map(g=>g.pages?.[q]).filter(Boolean),withData=candidates.filter(k=>hasData(values[k]));if(withData.length>1){conflict=true;break}pages[q]=withData[0]||candidates[0]||null}
     if(!conflict){target.pages=pages;target.enabledQuarters=pages.map((k,q)=>k?q:null).filter(q=>q!==null);for(const extra of same.slice(1)){if(item.examGroups.includes(extra))item.examGroups.splice(item.examGroups.indexOf(extra),1)}changed=true;log.push(where(subject,item)+': doppelte Bereiche „'+(target.label||kind)+'“ ('+(year.label||'Halbjahr')+') zusammengeführt')}
    }
    const group=groups.find(g=>kindOf(g)===kind&&g.halfYearId===year.id);if(!group)continue;group.pages??=[];
    // 2. Verwaiste Seiten mit Eintragungen wieder zuordnen
    if(kind==='performance'||kind==='homework'){
     const referenced=new Set(groups.flatMap(g=>g.pages||[]).filter(Boolean));
     for(const [key,data] of Object.entries(values)){
      if(referenced.has(key)||!hasData(data))continue;
      const list=kind==='performance'?data.tasks:data.assignments;if(!Array.isArray(list)||!list.length||!list.every(t=>t?.date))continue;
      if(kind==='performance'&&Array.isArray(data.assignments)&&data.assignments.length)continue;
      if(kind==='homework'&&!Array.isArray(data.assignments))continue;
      const first=list.map(t=>t.date).sort()[0],q=typeof classroomQuarterForDate==='function'?classroomQuarterForDate(year,first,-1):-1;if(q<0||q>3)continue;
      const current=group.pages[q];if(current&&hasData(values[current]))continue;
      group.pages[q]=key;referenced.add(key);changed=true;log.push(where(subject,item)+': Seite mit Eintragungen wieder dem '+(q+1)+'. Quartal von „'+(group.label||kind)+'“ ('+(year.label||'Halbjahr')+') zugeordnet');
     }
    }
    // 3. Quartale mit Eintragungen sichtbar halten
    if(Array.isArray(group.enabledQuarters)){group.pages.forEach((k,q)=>{if(k&&hasData(values[k])&&!group.enabledQuarters.includes(q)){group.enabledQuarters.push(q);changed=true;log.push(where(subject,item)+': '+(q+1)+'. Quartal von „'+(group.label||kind)+'“ mit Eintragungen wieder eingeblendet')}});group.enabledQuarters.sort((a,b)=>a-b)}
   }
  }
  return changed;
 }
 function repairAll(){
  let changed=false;
  try{for(const [subject,items] of Object.entries(classesBySubject||{}))for(const item of items||[])if(repairClass(subject,item))changed=true}catch(error){console.warn('Strukturprüfung übersprungen',error);return false}
  if(changed){try{persistClasses()}catch{}try{localStorage.setItem(storageKey,JSON.stringify(subjectStates))}catch{}try{if(subjects[currentSubject]){buildCustomSubjectPanels(currentSubject);refreshExamNavigation()}}catch{}}
  return changed;
 }
 window.classroomRepairStructure=()=>{log.length=0;const changed=repairAll();return {changed,log:[...log]}};
 repairAll();
})();
;

/* ==== noten/data-check.js ==== */
/* „Daten prüfen“ (aus dem Backup-Dialog): findet Unstimmigkeiten in den Bewertungsdaten.
   Automatisch behoben werden doppelte Bereiche, verwaiste Quartalsseiten und ausgeblendete Quartale mit Eintragungen
   (siehe structure-repair.js). Nur gemeldet werden Dinge, die eine Entscheidung brauchen:
   Seiten mit Eintragungen ohne Zuordnung, Zeilen ohne Namen mit Eintragungen und doppelte Namen. */
(()=>{
 const filled=v=>v!==''&&v!==null&&v!==undefined;
 const entries=s=>Object.values(s.grades||{}).some(filled)||Object.values(s.rawScores||{}).some(filled)||Object.values(s.statuses||{}).some(v=>filled(v)&&v!=='done')||filled(s.quarterReview?.teacher);
 const norm=v=>String(v||'').trim().toLocaleLowerCase('de-DE').replace(/\s+/g,' ');
 function pageLabel(subject,key){try{const p=customPagesFor(subject).find(p=>p.key===key);return p?.label||key}catch{return key}}
 function run(){
  const fixed=[],hints=[];
  try{const r=window.classroomRepairStructure?.();if(r?.log)fixed.push(...r.log)}catch(error){hints.push('Strukturprüfung nicht möglich: '+error.message)}
  for(const [subject,items] of Object.entries(classesBySubject||{})){
   const subjectLabel=subjects?.[subject]?.label||subject;
   for(const item of items||[]){
    const where=subjectLabel+' · '+(item.label||'Klasse'),values=subjectStates[`${subject}::class::${item.id}`]?.customValues;if(!values)continue;
    const referenced=new Set((item.examGroups||[]).flatMap(g=>g.pages||[]).filter(Boolean));
    for(const data of Object.values(values))for(const t of data?.tasks||[])if(t?.testDetail?.pageKey)referenced.add(t.testDetail.pageKey);
    for(const [key,data] of Object.entries(values)){
     const students=data?.students||[];
     if(!referenced.has(key)&&students.some(entries)){const items=[...(data.tasks||[]),...(data.assignments||[])],used=items.filter(t=>students.some(st=>filled(st.grades?.[t.id])||filled(st.rawScores?.[t.id])||(filled(st.statuses?.[t.id])&&st.statuses[t.id]!=='done'))),count=students.reduce((n,st)=>n+used.filter(t=>filled(st.grades?.[t.id])||filled(st.rawScores?.[t.id])||(filled(st.statuses?.[t.id])&&st.statuses[t.id]!=='done')).length,0),dates=[...new Set(used.map(t=>t.date).filter(Boolean))].sort().map(d=>d.split('-').reverse().join('.'));hints.push(where+': Eine Seite „'+pageLabel(subject,key)+'“ mit '+count+(count===1?' Eintrag':' Einträgen')+(dates.length?' ('+dates.join(', ')+')':'')+' ist keinem Bereich zugeordnet. Sie erscheint weder in der Navigation noch im Excel-Export.')}
     if(!referenced.has(key))continue;
     const unnamed=students.filter(s=>!String(s.name||'').trim()&&entries(s)).length;
     if(unnamed)hints.push(where+' · '+pageLabel(subject,key)+': '+unnamed+(unnamed===1?' Zeile ohne Namen enthält':' Zeilen ohne Namen enthalten')+' Eintragungen.');
     const seen=new Map();for(const s of students){const n=norm(s.name);if(!n)continue;seen.set(n,(seen.get(n)||0)+1)}
     const dups=[...seen].filter(([,c])=>c>1).map(([n])=>students.find(s=>norm(s.name)===n).name.trim());
     if(dups.length)hints.push(where+' · '+pageLabel(subject,key)+': doppelte Namen – '+dups.join(', ')+'.');
    }
   }
  }
  return {fixed,hints:[...new Set(hints)]};
 }
 window.classroomCheckData=run;
 window.addEventListener('message',event=>{
  if(event.source!==parent||event.data?.type!=='classroom:check-data')return;
  let report;try{report=run()}catch(error){parent.postMessage({type:'classroom:check-data-result',id:event.data.id,ok:false,message:error.message},'*');return}
  parent.postMessage({type:'classroom:check-data-result',id:event.data.id,ok:true,report},'*');
 });
})();
;

/* ==== noten/homework-symbols.js ==== */
/* Hausaufgaben und Material: Status als Symbol statt Text (✓ erledigt, ✗ fehlt, E entschuldigt, A abwesend, – nicht geprüft).
   Die bisherige Auswahlliste bleibt unsichtbar erhalten (Speichern, Tastatur, Export); darüber liegt ein kompakter Symbol-Button.
   Ein Tipp öffnet eine kleine Leiste mit allen fünf Symbolen – ein weiterer Tipp wählt. */
(()=>{
 const states=[['done','✓','Erledigt'],['missing','✗','Fehlt'],['excused','E','Entschuldigt'],['absent','A','Abwesend'],['','–','Nicht geprüft']];
 const info=v=>states.find(s=>s[0]===v)||states[4];
 let pop=null,current=null;
 function close(){pop?.remove();pop=null;current?.focus?.();current=null}
 function sync(select){const btn=select.previousElementSibling;if(!btn?.classList.contains('hw-symbol'))return;const [v,sym,label]=info(select.value);btn.textContent=sym;btn.dataset.status=v||'none';btn.classList.toggle('is-warning',select.classList.contains('homework-warning'));btn.title=label;btn.setAttribute('aria-label',(select.getAttribute('aria-label')||'Status')+': '+label)}
 function open(btn,select){
  close();current=btn;pop=document.createElement('div');pop.className='hw-symbol-pop';pop.setAttribute('role','menu');
  for(const [v,sym,label] of states){const o=document.createElement('button');o.type='button';o.className='hw-symbol-option';o.dataset.status=v||'none';o.textContent=sym;o.title=label;o.setAttribute('aria-label',label);o.setAttribute('role','menuitemradio');o.setAttribute('aria-checked',String(select.value===v));
   o.onclick=e=>{e.stopPropagation();if(select.value!==v){select.value=v;select.dispatchEvent(new Event('change',{bubbles:true}))}close()};pop.append(o)}
  document.body.append(pop);const r=btn.getBoundingClientRect(),w=pop.offsetWidth,h=pop.offsetHeight;
  pop.style.left=Math.max(6,Math.min(innerWidth-w-6,r.left+r.width/2-w/2))+'px';pop.style.top=(r.bottom+6+h<innerHeight?r.bottom+6:r.top-h-6)+'px';
  (pop.querySelector('[aria-checked="true"]')||pop.firstChild).focus();
 }
 function enhance(root){
  for(const select of root.querySelectorAll?.('select[data-homework-status]')||[]){
   if(select.previousElementSibling?.classList.contains('hw-symbol')){sync(select);continue}
   const btn=document.createElement('button');btn.type='button';btn.className='hw-symbol';btn.setAttribute('aria-haspopup','menu');
   btn.onclick=e=>{e.stopPropagation();open(btn,select)};select.before(btn);select.classList.add('hw-symbol-select');select.tabIndex=-1;sync(select);
  }
 }
 document.addEventListener('change',e=>{if(e.target.matches?.('select[data-homework-status]'))setTimeout(()=>enhance(document),0)},true);
 document.addEventListener('pointerdown',e=>{if(pop&&!pop.contains(e.target))close()},true);
 document.addEventListener('keydown',e=>{if(!pop)return;if(e.key==='Escape'){e.preventDefault();close()}else if(['ArrowLeft','ArrowRight'].includes(e.key)){const items=[...pop.children],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowRight'?1:-1)+items.length)%items.length].focus();e.preventDefault()}});
 addEventListener('scroll',()=>{if(pop)close()},true);
 const style=document.createElement('style');style.textContent=
  'body[data-module=noten] .homework-table select.hw-symbol-select{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important;overflow:hidden}'
  +'body[data-module=noten] .homework-table td:has(>.hw-symbol){text-align:center;position:relative}'
  +'.hw-symbol{display:inline-flex;align-items:center;justify-content:center;width:56px;height:32px;padding:0;border:1px solid #d7e0ec;border-radius:8px;background:#fff;color:#7a8698;font:inherit;font-size:17px;font-weight:700;line-height:1;cursor:pointer}'
  +'.hw-symbol:focus-visible,.hw-symbol-option:focus-visible{outline:3px solid #8ba9d1;outline-offset:2px}'
  +'.hw-symbol[data-status=done],.hw-symbol-option[data-status=done]{color:#15803d;background:#ecfdf3;border-color:#a7e3bd}'
  +'.hw-symbol[data-status=missing],.hw-symbol-option[data-status=missing]{color:#fff;background:#e5484d;border-color:#d93c42}'
  +'.hw-symbol[data-status=missing].is-warning{background:#b42318;border-color:#9b1c13}'
  +'.hw-symbol[data-status=excused],.hw-symbol-option[data-status=excused]{color:#315f99;background:#eef3fb;border-color:#c7d6ea;font-size:15px}'
  +'.hw-symbol[data-status=absent],.hw-symbol-option[data-status=absent]{color:#5b6472;background:#f1f3f6;border-color:#d5dbe3;font-size:15px}'
  +'.hw-symbol[data-status=none],.hw-symbol-option[data-status=none]{color:#9aa5b5;background:#fff}'
  +'.hw-symbol-pop{position:fixed;z-index:1000;display:flex;gap:6px;padding:6px;background:#fff;border:1px solid #dce3ef;border-radius:12px;box-shadow:0 12px 30px #1c2b4626}'
  +'.hw-symbol-option{width:40px;height:38px;border:1px solid #d7e0ec;border-radius:9px;background:#fff;font:inherit;font-size:18px;font-weight:700;cursor:pointer}'
  +'.hw-symbol-option[aria-checked=true]{box-shadow:0 0 0 2px #2f5f9b}'
  +'body[data-module=noten] .homework-table select[data-homework-status]:not(.hw-symbol-select){max-width:155px}';
 document.head.append(style);
 enhance(document);
 new MutationObserver(list=>{for(const m of list)for(const n of m.addedNodes)if(n.nodeType===1&&(n.matches?.('select[data-homework-status]')||n.querySelector?.('select[data-homework-status]'))){enhance(document);return}}).observe(document.body,{childList:true,subtree:true});
})();
;

/* ==== hatching.js ==== */
// Shared display preference; assessment values remain unchanged.
(()=>{
 const key='classroom-manager-hatching-v1';let enabled=localStorage.getItem(key)!=='off',queued=false;
 const style=document.createElement('style');style.textContent='[data-hatching-toggle][hidden]{display:none!important}html.hatching-off .classroom-unstriped:not(.grade-four-fail){background-image:none!important;background-color:var(--unstriped-color)!important}';document.head.append(style);
 const SEL='td span,td input,td select,td button,.cell,.classroom-rating-choice,.qs-big,.qs-edit input,.qs-sq i,.qs-val i,.qs-q1chip i,.qs-chip i,.qd-val';
 /* auch von den iPhone-Karten direkt aufrufbar (8.15) */
 function unstripe(root){for(const el of root.querySelectorAll(SEL)){const fill=getComputedStyle(el).backgroundImage;if(!fill.includes('gradient')||el.classList.contains('grade-four-fail'))continue;/* 4 Notenpunkte bleiben immer schraffiert. */el.classList.remove('classroom-unstriped');const base=getComputedStyle(el).backgroundColor,color=base&&!/rgba\(0, 0, 0, 0\)|transparent/.test(base)?base:fill.match(/rgba?\([^)]+\)|#[\da-f]{3,8}/i)?.[0];/* Ohne Schraffur gilt die Grundfarbe der Note (z. B. 2+ grün-gelb wie 2). */if(color){if(el.style.getPropertyValue('--unstriped-color')!==color)el.style.setProperty('--unstriped-color',color);if(!el.classList.contains('classroom-unstriped'))el.classList.add('classroom-unstriped')}}}
 window.classroomUnstripe=root=>{if(!enabled)unstripe(root||document)};
 /* 9.51: „Aus“ (weißer Kasten) – alle Bewertungsfelder ohne Farbe, für die ganze App (alle Rahmen). Gilt auch für 4 Notenpunkte. */
 const CKEY='classroom-manager-colors-off-v1';let colorsOff=localStorage.getItem(CKEY)==='on';
 const colored=el=>{const cs=getComputedStyle(el);if(cs.backgroundImage.includes('gradient'))return true;const m=cs.backgroundColor.match(/[\d.]+/g);if(!m||m.length<3||(m.length>3&&Number(m[3])===0))return false;const [r,g,b]=m.map(Number);return Math.max(r,g,b)-Math.min(r,g,b)>=20};
 function decolor(root){for(const el of root.querySelectorAll(SEL)){if(el.classList.contains('classroom-colorless')||el.classList.contains('classroom-rating-choice'))continue;if(el.classList.contains('cell')&&!el.classList.contains('classroom-seat-assessed'))continue;if(colored(el))el.classList.add('classroom-colorless')}}
 window.classroomColorsOff={get:()=>colorsOff,set:v=>{v=!!v;try{localStorage.setItem(CKEY,v?'on':'off')}catch{}if(colorsOff!==v){colorsOff=v;apply()}}};
 style.textContent+='html.colors-off body .classroom-colorless:not(#_):not(#__){background:#fff!important;background-image:none!important;color:#243247!important;box-shadow:inset 0 0 0 1px #d5deea!important}html.colors-off body .room-grid .cell.classroom-seat-assessed.classroom-colorless:not(#_):not(#__){box-shadow:none!important}';
 const gradCache=new WeakMap();
 function apply(){
  observer.disconnect();try{
  if(!enabled)unstripe(document);
  document.documentElement.classList.toggle('hatching-off',!enabled);
  document.documentElement.classList.toggle('colors-off',colorsOff);if(colorsOff)decolor(document);
  // Schraffuren-Schalter: neben „Kompaktansicht“, auf Übersichtsseiten ohne Kompaktansicht vor „Drucken“.
  const anchors=[...document.querySelectorAll('.compact-view-toggle')];
  for(const print of document.querySelectorAll('.section-title .page-print-button')){const title=print.closest('.section-title');if(!title.querySelector('.compact-view-toggle')){/* 10.49: Drucken steht unten bei den Aktionen – Schalter bleiben oben in der Ansicht-Zeile */const row1=title.querySelector(':scope>.oral-display-actions');anchors.push(row1&&print.parentElement!==row1?{parentElement:row1,before:l=>row1.append(l)}:print)}}
  for(const compact of anchors){const parent=compact.parentElement;if(!parent.querySelector(':scope>[data-hatching-toggle]')){const label=document.createElement('label');label.className='toggle';label.dataset.hatchingToggle='';label.title='Schraffuren in Bewertungsfeldern ein- oder ausblenden.';const input=document.createElement('input');input.type='checkbox';input.setAttribute('role','switch');const caption=document.createElement('span');caption.textContent='Schraffuren';label.append(input,caption);input.onchange=()=>{enabled=input.checked;localStorage.setItem(key,enabled?'on':'off');apply()};compact.before(label)}}
  document.querySelectorAll('[data-hatching-toggle] input').forEach(input=>input.checked=enabled);
  // Alle Anzeige-Schalter einer Seite stehen in der oberen Zeile vor „Schraffuren“: 1. Quartal, Zeichen/Noten, Tendenzen.
  for(const title of document.querySelectorAll('.section-title')){const hatch=title.querySelector('[data-hatching-toggle]');if(!hatch)continue;
   const wanted=['.previous-quarter-toggle','.task-participation-display']/* 10.51: „Tendenzen“ (Eingabe-Einstellung) bleibt unten bei den Extras */.map(s=>title.querySelector(s)).filter(Boolean);
   /* Umschalter-Segmente (seg-toggle) sitzen direkt bei ihrem Schalter und zählen hier nicht mit – sonst schieben sich die Skripte gegenseitig endlos hin und her. */let ok=true,node=hatch;for(let i=wanted.length-1;i>=0;i--){node=node.previousElementSibling;while(node&&node.matches('.seg-toggle,.hatch-seg'))node=node.previousElementSibling;if(node!==wanted[i]){ok=false;break}}
   if(!ok)for(const el of wanted)hatch.before(el)}
  // Schalter auf Seiten mit Noten immer zeigen; ohne Schraffur-Werte ausgegraut (8.45).
  for(const label of document.querySelectorAll('[data-hatching-toggle]')){const scope=label.closest('[data-custom-panel]')||label.closest('section,.panel,.card')||label.parentElement?.parentElement;if(!scope)continue;
   let any=!!scope.querySelector('.classroom-unstriped,.grade-four-fail,[class*=participation-between-]');
   /* 11.07: Die teure Stil-Abfrage je Zelle nur, wenn sich der Bereich geändert hat (vorher bei jeder Änderung irgendwo auf der Seite) */
   if(!any){const sig=scope.getElementsByTagName('*').length+':'+scope.textContent.length+':'+(scope.className||''),c=gradCache.get(scope);if(c&&c.sig===sig)any=c.any;else{for(const el of scope.querySelectorAll('td span,td input,td select,td button,.cell,.classroom-rating-choice')){if(getComputedStyle(el).backgroundImage.includes('gradient')){any=true;break}}gradCache.set(scope,{sig,any})}}
   /* 8.45: Auf Seiten mit Noten bleibt der Schalter immer sichtbar (einheitliche Kopfzeile); ohne Schraffur-Werte ist er nur ausgegraut.
      Seiten ohne Noten (Hausaufgaben, Material) zeigen ihn nicht. */
   let hw=!!scope.querySelector('[data-homework-status]');try{const k=scope.dataset?.customPanel;if(k&&typeof customPagesFor==='function'&&typeof currentSubject!=='undefined'&&customPagesFor(currentSubject).some(pg=>pg.key===k&&pg.system==='homework'))hw=true}catch{}const gradePage=!hw;const hide=!gradePage;if(label.hidden!==hide)label.hidden=hide;
   const none=gradePage&&!any;if((label.dataset.hatchNone==='1')!==none){if(none)label.dataset.hatchNone='1';else delete label.dataset.hatchNone}}
  try{window.classroomHatchSegPlace?.()}catch(e){console.error(e)}
  for(const label of document.querySelectorAll('[data-hatching-toggle]')){const seg=label.previousElementSibling;if(!seg?.classList.contains('hatch-seg'))continue;const none=label.dataset.hatchNone==='1'&&!colorsOff;
   for(const b of seg.querySelectorAll('[data-hatch]:not([data-hatch="white"])')){if(b.disabled!==none){b.disabled=none;if(none){b.dataset.tipOrig=b.title;b.title='Erst möglich, wenn es Tendenzen oder eine 4 gibt'}else if(b.dataset.tipOrig!==undefined){b.title=b.dataset.tipOrig;delete b.dataset.tipOrig}}}}
  }catch(e){console.error(e)}finally{observer.observe(document.body,{childList:true,subtree:true})}
 }
 const observer=new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;apply()})});
 window.addEventListener('storage',e=>{if(e.key===key){enabled=e.newValue!=='off';apply()}});window.addEventListener('storage',e=>{if(e.key===CKEY){colorsOff=e.newValue==='on';apply();window.classroomHatchSync?.()}});apply();
})();
;

/* ==== noten/exam-warning.js ==== */
// Informational thresholds for completed exam results only.
(()=>{
 const excluded=new Set(['halfYear','schoolYear','performance','homework','tests','quarterSummary','semester']);
 function examFailureStats(values,points){
  const results=values.filter(value=>value!==null&&value!==undefined&&Number.isFinite(value));
  const failed=results.filter(value=>points?Math.round(value)<=4:roundSchoolGrade(value)>=5).length;
  const limit=points?50:30,total=results.length;
  return {failed,total,limit,percent:total?failed/total*100:0,exceeded:total>0&&failed*100>limit*total};
 }
 window.classroomExamFailureStats=examFailureStats;
 function warning(subject,key){
  const group=subjectExamGroups(subject).find(g=>!excluded.has(g.type)&&!g.material&&g.pages.includes(key));
  if(!group)return null;
  const results=group.pages.find(k=>customPagesFor(subject).some(p=>p.key===k&&p.system==='tasks'))||group.pages.at(-1);
  if(results!==key)return null;
  const data=taskPageData(subject,key),points=taskGradeSystem(subject,key)==='gradePoints';
  const stats=examFailureStats(data.students.filter(s=>s.name?.trim()).map(s=>taskStudentResult(data,s)),points);
  return stats.exceeded?`${stats.limit}-%-Grenze überschritten: ${stats.failed} von ${stats.total} bewerteten Arbeiten ${points?'liegen bei 0–4 Notenpunkten':'sind mangelhaft oder ungenügend'} (${stats.percent.toLocaleString('de-DE',{maximumFractionDigits:2})} %).`:null;
 }
 function show(container,text){
  if(!container)return;
  let note=container.querySelector(':scope > .exam-failure-warning');
  if(!text){note?.remove();return}
  if(!note){note=document.createElement('p');note.className='exam-failure-warning';note.setAttribute('role','status');note.style.cssText='padding:12px 16px;border:1px solid #efc088;border-radius:10px;background:#fff1df;color:#93430b;font-weight:600';container.append(note)}
  note.textContent=text;
 }
 classroomHooks.add('renderTasksPage','exam-warning: Hinweis',{after(result,[subject,key]){show(document.querySelector(`[data-custom-panel="${CSS.escape(key)}"]`),warning(subject,key))}});
 classroomHooks.add('renderNotenspiegelTable','exam-warning: Hinweis im Notenspiegel',{after(result,[subject,key]){show($('notenspiegelTable').parentElement,warning(subject,key))}});
 for(const panel of document.querySelectorAll('[data-custom-panel]'))if(panel.querySelector('.task-table'))show(panel,warning(currentSubject,panel.dataset.customPanel));
})();
;

/* ==== noten/subject-settings.js ==== */
/* Fachspezifische Notengrenzen (Fachkonferenz): gelten ausschließlich für Klassen mit Schulnoten (Sek. I).
   Gespeichert wird eine Tendenzskala je Bewertungsart. Ganze Noten verwenden die Untergrenze des jeweiligen
   Notenbereichs (z. B. 4 = Grenze 4−), sodass „Grenze für ausreichend“ immer die Grenze zwischen 4− und 5+ ist. */
/* Als Funktionen statt Konstanten: In der zusammengefassten Release-Datei können diese Helfer schon beim Start (vor dieser Datei) aufgerufen werden. */
function subjectWholeIndex(){return [2,5,8,11,14,15]}
function subjectDefaultPass(){return {points:.5,errors:.15}}
function subjectAutoRatios(error,pass=error?subjectDefaultPass().errors:subjectDefaultPass().points){
 return error?[0,1/8,1/4,1/3,5/12,1/2,7/12,2/3,3/4,5/6,11/12,1,4/3,17/12,3/2,2].map(v=>v*pass):grades.map((_,i)=>i<=11?pass+(11-i)*(1-pass)/12:pass*[.75,.625,.5,.5][i-12]);
}
function subjectRound(v){return Math.round(v*100)/100}
function subjectGradeValue(index){return index===15?6:Math.floor(index/3)+1+(index%3-1)/3}
function subjectMigrateSettings(c){
 // Version 5.69 speicherte je nach Tendenz-Schalter unterschiedliche Schlüssel und unpassende Startwerte.
 const oldDefault=(value,error)=>error?(value===6?100:Math.min(100,Math.max(0,value*3.75))):Math.max(0,value<=4?100-value*12.5:50-(value-4)*25);
 const oldValue=label=>{const n=Number(label[0]);return label.length===1?n:label[1]==='+'?n-1/3:n+1/3};
 for(const basis of ['points','errors']){const error=basis==='errors',old=c[basis]||{},scale={};
  for(const [label,v] of Object.entries(old)){if(!Number.isFinite(Number(v))||Math.abs(Number(v)-oldDefault(oldValue(label),error))<1e-6)continue;if(c.tendencies)scale[label]=Number(v);else if(Number(label)<6)scale[label+'−']=Number(v)}
  c[basis]=scale}
 c.weightMode=c.ratio?'ratio':'percent';c.ratioOther=c.ratioother??c.other??50;c.ratioExams=c.ratioexams??c.exams??50;
 delete c.ratio;delete c.ratioother;delete c.ratioexams;c.version=2;return c;
}
function subjectGradeSettings(subject){const c=subjectStates.__subjectSettings?.[subject];if(!c)return null;if(c.version!==2)subjectMigrateSettings(c);return c;}
/* 9.89: Fachvorgabe Gewichtung innerhalb der Sonstigen Mitarbeit (Mündliche Mitarbeit : Tests) */
window.classroomSubjectOtherWeights=subject=>{const w=subjectStates?.__testDefaults?.[subject]?.otherWeights;if(!w)return null;const a=Number(w.participation),b=Number(w.tests);return Number.isFinite(a)&&Number.isFinite(b)&&a>=0&&b>=0&&Math.abs(a+b-100)<.001?{participation:a,tests:b}:null};
function subjectScaleActive(subject){return !!subjectGradeSettings(subject)&&classUsesSchoolGrades(subject);}
function subjectBoundary(config,basis,label){const v=Number(config?.[basis]?.[label]);if(Number.isFinite(v))return v;return subjectRound(subjectAutoRatios(basis==='errors')[grades.indexOf(label)]*100);}
/* Zeilen der Skala; ratio = Mindestanteil (Rohpunkte) bzw. Höchstanteil (Fehler). */
function subjectScaleRows(config,error,tendencies){
 const basis=error?'errors':'points',last=error?1:subjectBoundary(config,basis,'5−')/100;
 if(tendencies)return grades.map((label,index)=>({label,index,value:subjectGradeValue(index),key:'fk:'+label,ratio:index===15?last:subjectBoundary(config,basis,label)/100})).filter(r=>r.label!=='1+'||config.plus);
 return subjectWholeIndex().map((index,k)=>({label:String(k+1),index,value:k+1,key:'fk:w'+(k+1),ratio:k===5?last:subjectBoundary(config,basis,(k+1)+'−')/100}));
}
function subjectScaleFor(subject,error,tendencies){return subjectScaleActive(subject)?subjectScaleRows(subjectGradeSettings(subject),error,tendencies):null;}
function subjectPassFraction(subject,error){return subjectBoundary(subjectGradeSettings(subject),error?'errors':'points','4−')/100;}

/* Halbjahresgewichtung: bindende Vorgabe für die Halbjahresnote. */
function applySubjectSettings(subject,pageKey,saved){
 const config=subjectScaleActive(subject)?subjectGradeSettings(subject):(typeof klausurActive==='function'&&klausurActive(subject)?klausurSaved(subject):null);if(!config)return;
 if(!subjectExamGroups(subject).some(g=>g.type==='semester'&&g.pages?.includes(pageKey)))return;
 /* 9.65: Klausuren – Gewichtung nach Zahl der Klausuren im Halbjahr (bei 1 bzw. 2 Klausuren) */let other=config.other;
 if(config===klausurSaved(subject)&&Number.isFinite(Number(config.other2))){const sem=subjectExamGroups(subject).find(g=>g.type==='semester'&&g.pages?.includes(pageKey)),skip=new Set(['tests','semester','halfYear','performance','homework','quarterSummary','schoolYear']);const n=subjectExamGroups(subject).filter(g=>!skip.has(g.type)&&(!sem?.halfYearId||g.halfYearId===sem.halfYearId)).length;if(n>=2)other=Number(config.other2)}
 saved.finalWeights={other:subjectRound(other),exams:subjectRound(100-subjectRound(other))};
}
function subjectFinalWeightsLocked(subject){return subjectScaleActive(subject)||(typeof klausurActive==='function'&&klausurActive(subject)&&!!klausurSaved(subject));}

/* Klassenarbeitsseite: Fachvorgabe ersetzt die automatische Berechnung, Schalter bleiben bedienbar. */
function subjectPassField(subject,page,scale){
 const input=document.getElementById('custom-pass-'+page.key);if(!input)return;const section=input.closest('[data-custom-panel]');let hint=section?.querySelector('.subject-scale-hint');
 if(scale){if(!input.disabled)input.dataset.subjectOriginal=input.value;input.disabled=true;input.value=String(subjectRound(subjectPassFraction(subject,page.base==='text')*100));input.title='Fachspezifisch festgelegt: Zahnrad im Fenster „Fächer umbenennen“';
  if(!hint&&section){hint=document.createElement('p');hint.className='subject-scale-hint';section.querySelector('.custom-entry')?.after(hint)}if(hint)hint.textContent='Es gelten die fachspezifischen Notengrenzen von '+subjects[subject].label+'. Änderungen über das Zahnrad im Fenster „Fächer umbenennen“.';}
 else{if(input.disabled&&input.dataset.subjectOriginal!==undefined){input.value=input.dataset.subjectOriginal;delete input.dataset.subjectOriginal}input.disabled=false;input.removeAttribute('title');hint?.remove();}
}
const subjectOriginalTaskBasisConfig=taskBasisConfig;
taskBasisConfig=function(subject,key){const b=subjectOriginalTaskBasisConfig(subject,key);/* 11.54: Alternative Lateinarbeit bringt ihren eigenen Notenschlüssel mit */let own=false;try{own=!!customPageValues(subject,key)?.alaParts}catch{}if(!own&&b.system==='grades'&&subjectScaleActive(subject))b.pass=subjectPassFraction(subject,b.base==='text');return b;};
const subjectOriginalThresholdEntries=taskBasisThresholdEntries;
taskBasisThresholdEntries=function(subject,key,tendencies){
 const b=taskBasisConfig(subject,key);if(b.system!=='grades')return subjectOriginalThresholdEntries(subject,key,tendencies);
 let own=false;try{own=!!customPageValues(subject,key)?.alaParts}catch{}const scale=own?null:subjectScaleFor(subject,b.base==='text',!!tendencies);if(!scale)return subjectOriginalThresholdEntries(subject,key,tendencies);
 return scale.map(r=>{const stored=Number(b.manualPercentages?.[r.key]);return {...r,ratio:Number.isFinite(stored)?Math.min(100,Math.max(0,stored))/100:r.ratio}});
};
const subjectOriginalTaskRawValue=taskRawValue;
taskRawValue=function(subject,task,raw,tendencies){
 const b=taskBasisConfig(subject,task.basisPage);let own=false;try{own=!!customPageValues(subject,task.basisPage)?.alaParts}catch{}if(own||b.system!=='grades'||!subjectScaleActive(subject))return subjectOriginalTaskRawValue(subject,task,raw,tendencies);
 if(raw===''||raw==null||!Number.isFinite(Number(raw)))return null;
 const fraction=Number(raw)/Math.max(1,Number(task.maximum)||b.total),rows=taskBasisThresholdEntries(subject,task.basisPage,b.tendencies),error=b.base==='text';
 return (rows.find(r=>error?fraction<=r.ratio+1e-12:fraction>=r.ratio-1e-12)||rows.at(-1)).value;
};

/* Klausuren (Oberstufe, Notenpunkte): Fachvorgabe mit KMK-Standard (4 Punkte ab 40 %, 1 Punkt ab 20 %).
   Gilt für alle Fächer in Klassen mit Notenpunkten; einzeln gespeicherte Prozentwerte einer Berechnungsseite haben Vorrang. */
function klausurKMK(){return [95,90,85,80,75,70,65,60,55,50,45,40,33,27,20]}
function klausurDefaults(){const points={},errors={};klausurKMK().forEach((v,i)=>points[String(15-i)]=v);for(let p=15;p>=1;p--)errors[String(p)]=subjectRound(p>5?(15-p)/10*15:15+(5-p)*15/5);return {version:1,points,errors,other:50,exams:50,weightMode:'percent',ratioOther:1,ratioExams:1}}
function klausurSaved(subject){return subjectStates.__klausurSettings?.[subject]||null}
function klausurSettings(subject){const d=klausurDefaults(),c=klausurSaved(subject);return c?{...d,...c,points:{...d.points,...(c.points||{})},errors:{...d.errors,...(c.errors||{})}}:d}
function klausurActive(subject){try{return classUsesGradePoints(subject)}catch{return false}}
function klausurRatios(subject,error){const c=klausurSettings(subject),b=error?'errors':'points';return Array.from({length:16},(_,i)=>{const label=String(15-i);if(i===15)return error?1:0;return Math.max(0,Math.min(1,Number(c[b][label])/100))})}
{
 const prevEntries=taskBasisThresholdEntries;
 taskBasisThresholdEntries=function(subject,key,tendencies){const b=taskBasisConfig(subject,key);if(b.system!=='gradePoints'||!klausurActive(subject))return prevEntries(subject,key,tendencies);
  const ratios=klausurRatios(subject,b.base==='text');return ratios.map((r,i)=>{const label=String(15-i),k='grade:'+label,stored=Number(b.manualPercentages?.[k]);return {label,key:k,ratio:Number.isFinite(stored)?Math.min(100,Math.max(0,stored))/100:r}})};
 const prevConfig=taskBasisConfig;
 taskBasisConfig=function(subject,key){const b=prevConfig(subject,key);if(b.system==='gradePoints'&&klausurActive(subject))b.pass=klausurRatios(subject,b.base==='text')[10];return b};
}
/* Berechnungsseite (Notenpunkte): Fachvorgabe anzeigen, Feld „Grenze“ wie bei Klassenarbeiten sperren. */
function klausurScaleFor(subject,page){if(!klausurActive(subject))return null;return klausurRatios(subject,page.base==='text')}
function klausurPassField(subject,page,on){
 const input=document.getElementById('custom-pass-'+page.key);if(!input)return;const section=input.closest('[data-custom-panel]');let hint=section?.querySelector('.subject-scale-hint');
 if(on){if(!input.disabled)input.dataset.subjectOriginal=input.value;input.disabled=true;input.value=String(subjectRound(klausurRatios(subject,page.base==='text')[10]*100));input.title='Fachvorgabe für Klausuren: Zahnrad → Bewertungsgrenzen → Klausuren';
  if(!hint&&section){hint=document.createElement('p');hint.className='subject-scale-hint';section.querySelector('.custom-entry')?.after(hint)}if(hint)hint.textContent='Es gelten die Notengrenzen für Klausuren von '+subjects[subject].label+(klausurSaved(subject)?'':' (KMK-Standard: 4 Punkte ab 40 %)')+'. Änderungen über das Zahnrad → Bewertungsgrenzen → Klausuren.';}
 else{if(input.disabled&&input.dataset.subjectOriginal!==undefined){input.value=input.dataset.subjectOriginal;delete input.dataset.subjectOriginal}input.disabled=false;input.removeAttribute('title');hint?.remove()}
}

