  +'html body[data-module] .student-add-button.sr-toggle:not(#_):not(#__){box-sizing:border-box;display:inline-flex;align-items:center!important;line-height:21.6px!important;height:40px;padding:0 15px;border:1px dashed #b9c6d8;border-radius:10px;background:#fff;color:#2f5f9b;font-size:14.4px}html body[data-module] .student-add-button.sr-toggle[aria-pressed=true]:not(#_):not(#__){border-color:#d9867e;color:#b0453c}html body[data-module] .student-add-button.sr-toggle[aria-pressed=true]:hover:not(#_):not(#__){background:#fdf1ef}'+'@media print{.sr-add{visibility:hidden}}';document.head.append(st);
