   if(td.dataset.emptyUpgraded||!/^Noch keine Schüler:innen eingetragen\.?$/.test(td.textContent.trim()))continue;
   const panel=td.closest('[data-custom-panel]')||document;td.dataset.emptyUpgraded='1';
   td.innerHTML='<div class="empty-roster"><strong>Noch keine Schüler:innen in dieser Klasse.</strong><span>Namen einzeln anlegen oder eine Liste übernehmen (Text, Excel oder Klassenlisten-PDF).</span><div class="empty-roster-actions"><button type="button" data-empty-add>＋ Schüler:in</button><button type="button" data-empty-import>Import …</button></div></div>';
   td.querySelector('[data-empty-add]').onclick=()=>find(panel,/Schüler:in$/,false)?.click();
   td.querySelector('[data-empty-import]').onclick=()=>find(panel,/^Import/,true)?.click();
