   if(exams.length===1)box.append(sect(ka(exams[0]),we,kaMean(exams[0]),kaTile(exams[0]),0,{kind:'ka'}));else if(exams.length){box.append(caption('Klausuren',we,0));for(const e of exams)box.append(sect(ka(e),null,e,kaTile(e),1,{kind:'ka'}))}
