  let other=null;heads.forEach((h,k)=>{if(/^Sonstige Mitarbeit/.test(h)){const c=row.cells[k],sp=c?.querySelector('span'),tx=(sp||c)?.textContent.trim();if(tx&&tx!=='—'){const f=fmtMean(tx,sp?.className||'');other={text:f.text,cls:f.cls,soft:true,hint:'Vorschlag aus der Sonstigen Mitarbeit (noch keine Klassenarbeit)'}}return}if(!/^Halbjahresnote/.test(h))return;const c=row.cells[k];if(!c)return;const inp=c.querySelector('input');if(inp){if(inp.value.trim())set={text:inp.value.trim(),cls:inp.className.replace(/\bquarter-summary-input\b/,'')}}else{const sp=c.querySelector('span'),tx=(sp||c).textContent.trim();if(tx&&tx!=='—'){const f=fmtMean(tx,sp?.className||'');calc={text:f.text,cls:f.cls,soft:true}}}});
