 /* 8.01: Hinweise über den Karten – antippen filtert die Karten, nochmal antippen zeigt wieder alle */
 const FLAGS=[['ha','3× HA fehlend',c=>Number(c.dataset.haHalf)>=3],['mm','Ohne mündliche Note',c=>c.dataset.mmNow==='0']];
