/* ==== noten/student-notes.js ==== */
/* Kurze Notiz je Person (z. B. „Elterngespräch am 12.11.“), je Fach und Klasse.
   Gespeichert unter notenrechner-notizen-v1 – damit in Backup, Rückgängig und Geräte-Abgleich enthalten.
   iPhone: im Detailblatt der Karte bearbeiten, in der Karte unter dem Namen sichtbar.
   Mac/iPad: in der Quartalsübersicht ein Notiz-Symbol neben dem Namen (antippen = bearbeiten). */
(()=>{
 const KEY='notenrechner-notizen-v1';
 const norm=n=>String(n||'').trim().toLocaleLowerCase('de-DE');
 const all=()=>{try{const v=JSON.parse(localStorage.getItem(KEY)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}};
 const key=name=>(typeof currentSubject==='string'?currentSubject:'')+'::'+(typeof currentClassId==='string'?currentClassId:'')+'::'+norm(name);
 const txt=v=>typeof v==='string'?v:(v&&typeof v.t==='string'?v.t:'');
 const get=name=>txt(all()[key(name)]);
 function set(name,text){const a=all(),k=key(name);text=String(text||'').trim().slice(0,500);if(text)a[k]={t:text,n:String(name||'').trim()};else delete a[k];
  try{Object.keys(a).length?localStorage.setItem(KEY,JSON.stringify(a)):localStorage.removeItem(KEY)}catch{}
  document.dispatchEvent(new CustomEvent('classroom-student-note',{detail:{name}}));schedule()}
 /* Notizen der aktuellen Klasse (Fach + Klasse) mit Anzeigenamen */
 function list(){const pre=key('');const out=[];for(const [k,v] of Object.entries(all())){if(!k.startsWith(pre))continue;const t=txt(v);if(!t)continue;let n=v&&v.n;if(!n){const nk=k.slice(pre.length);n=[...document.querySelectorAll('[data-quarter-summary] tbody th[scope=row],.qs-name')].map(e=>[...e.childNodes].filter(x=>x.nodeType===3).map(x=>x.textContent).join('').trim()).find(x=>norm(x)===nk)||nk.replace(/(^|[\s,-])\S/g,c=>c.toUpperCase())}out.push({name:n,text:t})}return out.sort((a,b)=>a.name.localeCompare(b.name,'de'))}
 window.classroomStudentNotes={get,set,list,openList:()=>openList()};
 // Mac/iPad: Symbol in der Quartalsübersicht (Name-Zelle bleibt textlich unverändert, das Symbol hat keinen Text)
 let planned=false;const schedule=()=>{if(planned)return;planned=true;requestAnimationFrame(()=>{planned=false;marks()})};
 function marks(){for(const th of document.querySelectorAll('[data-quarter-summary] tbody th[scope=row]')){
  const name=[...th.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();if(!name)continue;
  const note=get(name);let b=th.querySelector(':scope>.sn-mark');
  if(!b){b=document.createElement('button');b.type='button';b.className='sn-mark';th.append(b)}
  if(!b._sn){b._sn=1;b.onclick=async e=>{e.stopPropagation();e.preventDefault();const v=await (window.classroomPrompt||prompt)('Notiz zu '+name+' (leer lassen zum Löschen):',get(name));if(v!==null&&v!==undefined)set(name,v)}}
  const has=!!note;if(b.classList.contains('has-note')!==has)b.classList.toggle('has-note',has);const t=has?'Notiz: '+note:'Notiz hinzufügen';if(b.title!==t){b.title=t;b.setAttribute('aria-label',t)}}}
 new MutationObserver(list=>{if(list.some(m=>[...m.addedNodes].some(n=>n.nodeType===1&&!n.classList?.contains('sn-mark'))))schedule()}).observe(document.documentElement,{childList:true,subtree:true});
 /* 8.17: Hinweis „📝 2 Notizen in dieser Klasse“ über den Seiten (Mac/iPad; auf dem iPhone als Hinweis über den Karten) */
 let banner=null,bSig='';
 function updateBanner(){const host=document.getElementById('customPanels');if(!host)return;const l=list(),sig=(typeof currentSubject==='string'?currentSubject:'')+'|'+(typeof currentClassId==='string'?currentClassId:'')+'|'+l.map(x=>x.name+':'+x.text).join('|');if(sig===bSig&&banner?.isConnected)return;bSig=sig;
  if(!banner){banner=document.createElement('button');banner.type='button';banner.className='sn-banner';banner.onclick=()=>openList()}
  if(banner.nextElementSibling!==host)host.before(banner);banner.hidden=!l.length;banner.innerHTML=l.length?'<span aria-hidden="true">📝</span> <b>'+l.length+(l.length===1?' Notiz':' Notizen')+'</b> in dieser Klasse: '+l.slice(0,3).map(x=>esc(x.name.split(',')[1]?.trim()||x.name)).join(', ')+(l.length>3?' …':'')+' <u>anzeigen</u>':''}
 const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 let dlg=null;
 function openList(){dlg?.remove();dlg=document.createElement('div');dlg.className='sn-dlg';dlg.innerHTML='<div class="sn-back"></div><section class="sn-panel" role="dialog" aria-label="Notizen"><div class="sn-head"><b>Notizen in dieser Klasse</b><button type="button" class="sn-x" aria-label="Schließen">✕</button></div><div class="sn-body"></div></section>';document.body.append(dlg);
  const close=()=>{dlg?.remove();dlg=null};dlg.querySelector('.sn-back').onclick=close;dlg.querySelector('.sn-x').onclick=close;/* 8.23: auf dem iPhone nach unten wegwischen */{const pn=dlg.querySelector('.sn-panel'),bd=dlg.querySelector('.sn-body');let y0=null,dy=0;pn.addEventListener('touchstart',e=>{if(bd.contains(e.target)&&bd.scrollTop>0)return;y0=e.touches[0].clientY;dy=0;pn.style.transition='none'},{passive:true});pn.addEventListener('touchmove',e=>{if(y0===null)return;dy=e.touches[0].clientY-y0;if(dy>6){pn.style.transform='translateY('+dy+'px)';if(e.cancelable)e.preventDefault()}},{passive:false});pn.addEventListener('touchend',()=>{if(y0===null)return;y0=null;pn.style.transition='transform .18s ease';if(dy>90){pn.style.transform='translateY(100%)';setTimeout(close,180)}else pn.style.transform=''},{passive:true})}
  const render=()=>{const body=dlg.querySelector('.sn-body'),l=list();body.innerHTML=l.length?l.map((x,i)=>'<div class="sn-item"><b>'+esc(x.name)+'</b><p>'+esc(x.text)+'</p><div class="sn-act"><button type="button" data-edit="'+i+'">Bearbeiten</button><button type="button" data-done="'+i+'" class="sn-done">✓ Erledigt</button></div></div>').join(''):'<p class="sn-none">Keine Notizen mehr in dieser Klasse.</p>';
   body.onclick=async e=>{const b=e.target.closest('button');if(!b)return;const x=l[Number(b.dataset.edit??b.dataset.done)];if(!x)return;if(b.dataset.done!==undefined){set(x.name,'');render();return}const v=await (window.classroomPrompt||prompt)('Notiz zu '+x.name+':',x.text);if(v!==null&&v!==undefined){set(x.name,v);render()}}};render()}
 new MutationObserver(()=>{requestAnimationFrame(updateBanner)}).observe(document.documentElement,{attributes:true,attributeFilter:['class']});
 document.addEventListener('classroom-student-note',()=>requestAnimationFrame(updateBanner));
 if(typeof classroomHooks!=='undefined'){try{classroomHooks.add('refreshExamNavigation','student-notes: Hinweis',{after(){requestAnimationFrame(updateBanner)}})}catch{}}
 addEventListener('storage',e=>{if(e.key===KEY){schedule();updateBanner()}});schedule();setTimeout(updateBanner,800);
 const st=document.createElement('style');st.textContent='.sn-mark{display:inline-block;vertical-align:middle;width:20px;height:20px;margin-left:6px;padding:0;border:0;border-radius:6px;background:transparent;cursor:pointer;opacity:0;-webkit-mask:var(--sn) center/15px no-repeat;mask:var(--sn) center/15px no-repeat;background-color:#8794a7;--sn:url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27black%27 stroke-width=%272.2%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M4 4h16v12H8l-4 4z%27/%3E%3Cpath d=%27M8 9h8M8 12h5%27/%3E%3C/svg%3E")}'
  +'tr:hover .sn-mark,.sn-mark:focus-visible{opacity:.6}.sn-mark.has-note{opacity:1;background-color:#d08a1f}'
  +'.sn-banner{display:flex;align-items:center;gap:6px;width:100%;box-sizing:border-box;margin:0 0 10px;padding:8px 12px;border:1px solid #f0d9a8;border-radius:10px;background:#fff7e0;color:#7a5410;font:inherit;font-size:13.5px;text-align:left;cursor:pointer}.sn-banner[hidden]{display:none}.sn-banner u{margin-left:auto;color:#2f5f9b;text-decoration:none;font-weight:650;white-space:nowrap}'
  +'html.ph-lite .sn-banner{display:none!important}'
  +'.sn-dlg{position:fixed;inset:0;z-index:9800}.sn-back{position:absolute;inset:0;background:#1c2b4655}.sn-panel{position:absolute;left:50%;top:12vh;transform:translateX(-50%);width:min(520px,calc(100vw - 24px));max-height:76vh;display:flex;flex-direction:column;background:#fff;border-radius:16px;box-shadow:0 18px 50px #1c2b4640}'
  +'.sn-head{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid #eef2f7}.sn-head b{font-size:16px}.sn-x{width:36px;height:36px;border:0;background:none;color:#66758a;font-size:16px;cursor:pointer}'
  +'.sn-body{overflow:auto;padding:10px 16px 16px}.sn-item{padding:10px 0;border-bottom:1px solid #eef2f7}.sn-item p{margin:4px 0 8px;color:#243247;line-height:1.4}.sn-act{display:flex;gap:8px}.sn-act button{min-height:34px;padding:0 12px;border:1px solid #cbd6e5;border-radius:9px;background:#fff;color:#2f5f9b;font:inherit;font-size:13px;cursor:pointer}.sn-act .sn-done{border-color:#9fd3b4;color:#1f7a45;background:#f1faf4}.sn-none{color:#8794a7}'
  +'@media (max-width:540px) and (orientation:portrait),(max-height:500px) and (orientation:landscape) and (pointer:coarse){.sn-panel{left:0;right:0;top:auto;bottom:0;transform:none;width:auto;border-radius:20px 20px 0 0;padding-bottom:env(safe-area-inset-bottom)}.sn-panel::before{content:"";display:block;width:40px;height:5px;border-radius:3px;background:#cbd6e5;margin:8px auto 0}}'
  +'@media print{.sn-mark,.sn-banner{display:none}}html.classroom-privacy .sn-mark,html.classroom-privacy .sn-banner{display:none!important}html.classroom-privacy .sn-item :is(b,p){color:transparent!important;text-shadow:0 0 7px rgba(36,51,71,.75)!important}';document.head.append(st);
})();
;

/* ==== no-contacts.js ==== */
/* Safari/iOS soll bei Schülernamen keine Einträge aus den eigenen Kontakten vorschlagen (Datenschutz, z. B. am Beamer).
   Namensfelder erhalten autocomplete="off" und ein name-Attribut, das Safari nicht als Kontaktfeld erkennt. */
(()=>{
 const sel='input[type=text],input[type=search],input:not([type])';
 let n=0;
 function protect(input){
  if(input.dataset.noContacts)return;
  const hint=((input.placeholder||'')+' '+(input.getAttribute('aria-label')||'')+' '+(input.name||'')+' '+(input.id||'')).toLowerCase();
  if(!/name|schüler|person/.test(hint))return;
  input.dataset.noContacts='1';input.autocomplete='off';
  for(const [k,v] of Object.entries({autocorrect:'off','data-lpignore':'true','data-1p-ignore':'true','data-form-type':'other'}))input.setAttribute(k,v);
  if(!input.name||/name/i.test(input.name))input.name='search-roster-'+(++n);
 }
 function scan(root){if(root.matches?.(sel))protect(root);root.querySelectorAll?.(sel).forEach(protect)}
 scan(document);
 new MutationObserver(list=>{for(const m of list)for(const node of m.addedNodes)if(node.nodeType===1)scan(node)}).observe(document.documentElement,{childList:true,subtree:true});
 // Nachträglich gesetzte Platzhalter/Bezeichnungen ebenfalls prüfen.
 document.addEventListener('focusin',e=>{if(e.target.matches?.(sel))protect(e.target)},true);
})();
;
